const BELT_ORDER = ["white", "yellow", "orange", "green", "blue", "purple", "brown", "black"];
const abilitiesForBelt = (belt, mode = "drills") => {
  const idx = BELT_ORDER.indexOf(belt);
  const pool = mode === "spar" ? ABILITIES_SPAR : ABILITIES_DRILLS;
  return pool.filter((a) => BELT_ORDER.indexOf(a.belt) <= idx);
};

// HP scaling per belt — White 100 ramping to Black 600, +5 per level within a belt
const BELT_HP = { white: 100, yellow: 130, orange: 170, green: 220, blue: 290, purple: 370, brown: 470, black: 600 };

// === CARRY-OVER FLOORS ===
// Each belt's L1 stats should be no worse than the previous belt's L20.
// Otherwise, getting promoted Orange L20 → Green L1 makes you weaker because
// the +5 HP / +0.05× damage per-level scaling outpaces the belt's natural base.
// We precompute a "floor" per belt that respects monotonic progression across
// belt promotions, then use those floors in hpFor() and damageFor().
const BELT_FLOORS = (() => {
  const floors = {};
  let prevL20Hp = 0;
  let prevL20Mult = 0;
  for (const belt of BELT_ORDER) {
    const naturalHp = BELT_HP[belt];
    const naturalMult = BATTLE_BELTS[belt].mult;
    const floorHp = Math.max(naturalHp, prevL20Hp);
    const floorMult = Math.max(naturalMult, prevL20Mult);
    floors[belt] = { hp: floorHp, mult: floorMult };
    prevL20Hp = floorHp + 20 * 5;       // 20 levels × +5 HP per level
    prevL20Mult = floorMult + 20 * 0.05; // 20 levels × +0.05× per level
  }
  return floors;
})();

const hpFor = (belt, level) => BELT_FLOORS[belt].hp + level * 5;
const damageFor = (belt, level) => Math.round(15 * (BELT_FLOORS[belt].mult + level * 0.05));

