                  width: `${(totalDone / 50) * 100}%`,
                  background: "linear-gradient(90deg, #5BC890, #7BD8A8 50%, #5BC890)",
                  backgroundSize: "200% 100%",
                  animation: "shimmer 2.6s linear infinite",
                  transition: "width 600ms cubic-bezier(0.16, 1, 0.3, 1)",
