/* ============================================================
   LEVEL UP / NEW BELT — celebration modal.
   Pops over everything when the user crosses a level or belt threshold.
   Shows OLD → NEW stats (HP and damage) with arrow animations.
   New-belt variant also shows the new belt graphic + any unlocked ability.
   ============================================================ */

/* ============================================================
   LEVEL UP / NEW BELT — celebration modal.
   Matches the visual language of the Puffling profile modal:
   white card with gold gradient border, big Puffling in a
   gold-trimmed circular badge, corner sparkles, clean stat rows.
   Pops over everything when the user crosses a level/belt threshold.
   Two variants: "levelUp" (within same belt) and "newBelt"
   (crossed into next belt — bigger flourish, belt transition,
   ability unlock card).
   ============================================================ */
const LevelUpModal = ({ info, pufflingName, onClose }) => {
  if (!info) return null;
  const isNewBelt = info.type === "newBelt";
  const hpDelta = info.toHp - info.fromHp;
  const dmgDelta = info.toDmg - info.fromDmg;
  const displayName = pufflingName && pufflingName.trim() ? pufflingName : "Your Puffling";
  const beltLabel = (info.toBelt || "white").toUpperCase() + " BELT";
  const levelLabel = `LEVEL ${info.toLevel}`;

  // Belt color lookup for the pill — uses the same palette as the rest of the app
  const beltColors = {
    white:  { light: "#FFFFFF", dark: "#E8E8E8", text: "#3D2A05" },
    yellow: { light: "#FFE066", dark: "#FFC940", text: "#3D2A05" },
    orange: { light: "#FFB066", dark: "#FF8030", text: "white" },
    green:  { light: "#7BD8A8", dark: "#4AA078", text: "white" },
    blue:   { light: "#6BC4F0", dark: "#3A8BC0", text: "white" },
    purple: { light: "#B69AE8", dark: "#7A52B5", text: "white" },
    brown:  { light: "#9B6E3D", dark: "#5A3A1A", text: "white" },
    black:  { light: "#3A3A3A", dark: "#1A1A1A", text: "white" },
  };
  const beltC = beltColors[info.toBelt] || beltColors.white;

  return (
    <div
      className="absolute inset-0 flex items-center justify-center px-5"
      style={{
        background: isNewBelt
          ? "radial-gradient(ellipse at 50% 40%, rgba(255,224,102,0.55) 0%, rgba(255,150,50,0.4) 35%, rgba(7, 58, 44, 0.7) 100%)"
          : "rgba(7, 58, 44, 0.55)",
        backdropFilter: "blur(6px)",
        WebkitBackdropFilter: "blur(6px)",
        zIndex: 50,
        animation: "modalFadeIn 220ms ease-out",
      }}
      onClick={onClose}
    >
      {/* Confetti behind the card (new belt only) */}
      {isNewBelt && (
        <>
          {Array.from({ length: 22 }).map((_, i) => (
            <div key={i} className="absolute pointer-events-none" style={{
              top: -10,
              left: `${(i * 4.5 + 3) % 100}%`,
              fontSize: 12 + (i % 4) * 4,
              animation: `sparkRise ${2.4 + (i % 5) * 0.3}s linear ${i * 0.12}s infinite`,
              color: ["#FFD83A", "#FFA94D", "#E8444E", "#5BC890", "#4BBCF0", "#9F7AEA"][i % 6],
              textShadow: "0 0 6px rgba(255,255,255,0.5)",
            }}>{i % 3 === 0 ? "✦" : i % 3 === 1 ? "★" : "●"}</div>
          ))}
        </>
      )}

      {/* Card — stop propagation so taps inside don't close */}
      <div
        onClick={(e) => e.stopPropagation()}
        className="relative"
        style={{
          width: "85%",
          maxWidth: 340,
          background: "linear-gradient(180deg, #FFFFFF 0%, #FFFBEF 100%)",
          borderRadius: 28,
          padding: "22px 20px 18px 20px",
          boxShadow: "0 18px 48px rgba(7, 58, 44, 0.4), inset 0 1.5px 0 rgba(255,255,255,0.8)",
          border: "3px solid transparent",
          backgroundImage: "linear-gradient(180deg, #FFFFFF 0%, #FFFBEF 100%), linear-gradient(135deg, #FFD83A 0%, #FFA94D 50%, #FFD83A 100%)",
          backgroundOrigin: "border-box",
          backgroundClip: "padding-box, border-box",
          animation: "modalPopIn 380ms cubic-bezier(0.34, 1.56, 0.64, 1)",
        }}
      >
        {/* Corner sparkles */}
        <div className="absolute" style={{ top: 12, left: 16, fontSize: 14, color: "#FFD83A", animation: "sparkle 2.4s ease-in-out infinite" }}>✦</div>
        <div className="absolute" style={{ top: 14, right: 50, fontSize: 12, color: "#FFA94D", animation: "sparkle 2.6s ease-in-out 0.7s infinite" }}>✦</div>
        <div className="absolute" style={{ bottom: 14, left: 22, fontSize: 12, color: "#FFA94D", animation: "sparkle 2.8s ease-in-out 1.2s infinite" }}>✦</div>
        <div className="absolute" style={{ bottom: 80, right: 18, fontSize: 14, color: "#FFD83A", animation: "sparkle 2.5s ease-in-out 0.4s infinite" }}>✦</div>

        {/* Close button */}
        <button
          onClick={onClose}
          className="absolute tactile rounded-full flex items-center justify-center"
          style={{
            top: 10, right: 10,
            width: 32, height: 32,
            background: "rgba(7, 58, 44, 0.06)",
            color: "#3D2A05",
            fontSize: 16,
            fontWeight: 700,
            border: "none",
            cursor: "pointer",
          }}
          aria-label="Close"
        >
          ✕
        </button>

        {/* Banner — "LEVEL UP" or "NEW BELT EARNED" */}
        <div className="text-center" style={{ paddingRight: 30, paddingLeft: 30 }}>
          <div
            className="font-display font-bold uppercase"
            style={{
              fontSize: 10,
              color: isNewBelt ? "#B92020" : "#7A4A1A",
              letterSpacing: "0.22em",
              marginBottom: 4,
            }}
          >
            {isNewBelt ? "🎉  NEW BELT EARNED  🎉" : "✦  LEVEL UP  ✦"}
          </div>
          {/* Headline — Puffling name */}
          <div
            className="font-display font-bold"
            style={{
              fontSize: 26,
              color: "#3D2A05",
              lineHeight: 1,
              textShadow: "0 2px 0 rgba(255, 232, 154, 0.6)",
              letterSpacing: "-0.01em",
            }}
          >
            {displayName}
          </div>
          {/* Subheadline — what happened */}
          <div
            className="font-display font-semibold"
            style={{
              fontSize: 13,
              color: "#7A4A1A",
              marginTop: 4,
              lineHeight: 1.2,
            }}
          >
            {isNewBelt
              ? `Promoted to ${beltLabel.split(" ")[0].charAt(0) + beltLabel.split(" ")[0].slice(1).toLowerCase()} Belt!`
              : `Reached Level ${info.toLevel}!`}
          </div>
        </div>

        {/* Puffling in a gold-trimmed circular badge — bigger animation for new belt */}
        <div className="flex justify-center mt-3">
          <div
            className="relative rounded-full flex items-center justify-center"
            style={{
              width: 156, height: 156,
              background: "linear-gradient(135deg, #FFD83A 0%, #FFA94D 50%, #FFD83A 100%)",
              padding: 4,
              boxShadow: isNewBelt
                ? "0 6px 24px rgba(255, 169, 77, 0.7), 0 0 40px rgba(255, 216, 58, 0.4)"
                : "0 6px 18px rgba(255, 169, 77, 0.4)",
              animation: isNewBelt ? "modalPopIn 600ms cubic-bezier(0.34, 1.56, 0.64, 1) 200ms both" : "none",
            }}
          >
            <div
              className="rounded-full flex items-center justify-center"
              style={{
                width: "100%", height: "100%",
                background: "radial-gradient(circle, #FFFBEF 0%, #FFE89A 100%)",
              }}
            >
              <Puffling state="triumph" size={130} belt={info.toBelt} />
            </div>
            {/* Orbiting sparkles around the badge */}
            <div className="absolute" style={{ top: -6, right: 12, fontSize: 22, animation: "sparkleSpin 2.4s ease-in-out infinite" }}>✨</div>
            <div className="absolute" style={{ bottom: 8, left: -8, fontSize: 18, animation: "sparkleSpin 2.8s ease-in-out infinite 0.7s" }}>✨</div>
            {isNewBelt && (
              <div className="absolute" style={{ top: 30, left: -12, fontSize: 16, animation: "sparkleSpin 2.2s ease-in-out infinite 1.3s" }}>✨</div>
            )}
          </div>
        </div>

        {/* Belt + level pill — same style as profile modal */}
        <div className="flex justify-center mt-3">
          <div
            className="rounded-full font-display font-bold flex items-center gap-1.5"
            style={{
              padding: "5px 14px",
              background: `linear-gradient(180deg, ${beltC.light} 0%, ${beltC.dark} 100%)`,
              fontSize: 11,
              color: beltC.text,
              letterSpacing: "0.08em",
              boxShadow: "0 3px 0 rgba(0,0,0,0.12), inset 0 1px 0 rgba(255,255,255,0.4)",
              border: "1.5px solid rgba(0,0,0,0.08)",
            }}
          >
            <span>{beltLabel}</span>
            <span style={{ opacity: 0.7 }}>·</span>
            <span>{levelLabel}</span>
          </div>
        </div>

        {/* Section divider with ⚡ STAT UPGRADE label */}
        <div className="flex items-center gap-2 mt-5">
          <div style={{ flex: 1, height: 1, background: "linear-gradient(90deg, transparent 0%, rgba(255, 169, 77, 0.5) 100%)" }} />
          <span className="font-display font-bold uppercase flex items-center gap-1.5" style={{ fontSize: 10, color: "#7A4A1A", letterSpacing: "0.16em" }}>
            <span>⚡</span>
            <span>Stat Upgrade</span>
          </span>
          <div style={{ flex: 1, height: 1, background: "linear-gradient(90deg, rgba(255, 169, 77, 0.5) 0%, transparent 100%)" }} />
        </div>

        {/* Stat rows — OLD → NEW with delta pill */}
        <div className="mt-3 flex flex-col gap-2">
          <UpgradeStatRow
            icon="❤️"
            label="HP"
            from={info.fromHp}
            to={info.toHp}
            delta={hpDelta}
            accent="linear-gradient(180deg, #FFB3A8 0%, #E8444E 100%)"
            shadow="#A82530"
          />
          <UpgradeStatRow
            icon="⚔️"
            label="DAMAGE"
            from={info.fromDmg}
            to={info.toDmg}
            delta={dmgDelta}
            accent="linear-gradient(180deg, #FFE066 0%, #F5C81A 100%)"
            shadow="#C99227"
          />
        </div>

        {/* Ability unlock (new belt only) */}
        {isNewBelt && info.newAbility && (
          <>
            <div className="flex items-center gap-2 mt-4">
              <div style={{ flex: 1, height: 1, background: "linear-gradient(90deg, transparent 0%, rgba(255, 169, 77, 0.5) 100%)" }} />
              <span className="font-display font-bold uppercase flex items-center gap-1.5" style={{ fontSize: 10, color: "#7A4A1A", letterSpacing: "0.16em" }}>
                <span>🔓</span>
                <span>Ability Unlocked</span>
              </span>
              <div style={{ flex: 1, height: 1, background: "linear-gradient(90deg, rgba(255, 169, 77, 0.5) 0%, transparent 100%)" }} />
            </div>
            <div
              className="mt-3 rounded-2xl flex items-center gap-3"
              style={{
                padding: "12px 14px",
                background: "linear-gradient(180deg, rgba(255, 224, 102, 0.25) 0%, rgba(255, 169, 77, 0.15) 100%)",
                border: "1.5px solid rgba(255, 169, 77, 0.5)",
                boxShadow: "0 3px 0 rgba(0,0,0,0.05), 0 6px 14px rgba(255, 169, 77, 0.15)",
              }}
            >
              <div
                className="rounded-xl flex items-center justify-center flex-shrink-0"
                style={{
                  width: 44, height: 44,
                  background: "linear-gradient(180deg, #FFE066 0%, #FFA94D 60%, #E87822 100%)",
                  boxShadow: "0 2px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.4)",
                  fontSize: 22,
                }}
              >
                {info.newAbility.icon}
              </div>
              <div className="flex-1">
                <div className="font-display font-bold" style={{ fontSize: 14, color: "#3D2A05", letterSpacing: "0.04em", lineHeight: 1 }}>
                  {info.newAbility.name}
                </div>
                <div className="font-body font-semibold" style={{ fontSize: 11, color: "rgba(122, 74, 26, 0.85)", lineHeight: 1.3, marginTop: 3 }}>
                  {info.newAbility.desc}
                </div>
              </div>
            </div>
          </>
        )}

        {/* Continue button */}
        <button
          onClick={onClose}
          className="tactile cta-pulse font-display font-bold"
          style={{
            marginTop: 16,
            width: "100%",
            padding: "12px 16px",
            borderRadius: 14,
            background: "linear-gradient(180deg, #FFE066 0%, #FFA94D 60%, #E87822 100%)",
            color: "#3D2A05",
            border: "none",
            fontSize: 15,
            letterSpacing: "0.16em",
            boxShadow: "0 4px 0 #B85020, 0 6px 14px rgba(255, 169, 77, 0.35), inset 0 1px 0 rgba(255,255,255,0.5)",
            textShadow: "0 1px 0 rgba(255,255,255,0.3)",
          }}
        >
          CONTINUE ⚔
        </button>
      </div>

      <style>{`
        @keyframes modalFadeIn {
          from { opacity: 0; }
          to   { opacity: 1; }
        }
        @keyframes modalPopIn {
          0%   { transform: scale(0.82); opacity: 0; }
          60%  { transform: scale(1.04); opacity: 1; }
          100% { transform: scale(1);    opacity: 1; }
        }
      `}</style>
    </div>
  );
};

/* Single stat upgrade row — icon square + label + old → new + delta pill */
const UpgradeStatRow = ({ icon, label, from, to, delta, accent, shadow }) => {
  const isPositive = delta > 0;
  const deltaColor = isPositive ? "#3A9560" : "#B82530";
  const deltaBg = isPositive ? "rgba(91,200,144,0.18)" : "rgba(232,68,78,0.18)";
  return (
    <div
      className="rounded-2xl flex items-center gap-3"
      style={{
        padding: "10px 14px",
        background: "white",
        boxShadow: "0 3px 0 rgba(0,0,0,0.05), 0 6px 14px rgba(255, 169, 77, 0.12)",
        border: "1px solid rgba(255, 169, 77, 0.18)",
      }}
    >
      <div
        className="rounded-xl flex items-center justify-center flex-shrink-0"
        style={{
          width: 38, height: 38,
          background: accent,
          boxShadow: `0 2px 0 ${shadow}, inset 0 1px 0 rgba(255,255,255,0.4)`,
          fontSize: 18,
        }}
      >
        {icon}
      </div>
      <div className="flex-1 flex items-center justify-between">
        <div className="font-display font-bold uppercase" style={{ fontSize: 11, color: "#5A3A1A", letterSpacing: "0.12em" }}>
          {label}
        </div>
        <div className="flex items-center gap-2 font-display font-bold" style={{ fontVariantNumeric: "tabular-nums" }}>
          <span style={{ fontSize: 14, color: "rgba(58,42,5,0.4)", textDecoration: "line-through" }}>{from}</span>
          <span style={{ fontSize: 12, color: "#7A5A20" }}>→</span>
          <span style={{ fontSize: 20, color: "#3D2A05" }}>{to}</span>
          <span className="font-body font-bold" style={{
            fontSize: 11,
            color: deltaColor,
            background: deltaBg,
            padding: "2px 7px",
            borderRadius: 999,
            letterSpacing: "0.04em",
            minWidth: 32,
            textAlign: "center",
          }}>
            {isPositive ? `+${delta}` : delta}
          </span>
        </div>
      </div>
    </div>
  );
};


/* ============================================================
   SOCIAL — UTILITY: AVATAR with story/online rings + flag chip.
   Used everywhere a user shows up. Has multiple visual states:
   - default: round colored disc with initial
   - online: pulsing green dot in bottom-right
   - liveDuel: rotating red/gold gradient ring around it
   - storyRing: gradient ring (active in last 24h)
   ============================================================ */
const UserAvatar = ({ user, size = 48, ring = "none", showCountry = false }) => {
  const padding = ring === "none" ? 0 : 3;
  const inner = size - padding * 2;
  // Decide ring background by state
  let ringBg = "transparent";
  let ringAnimation = "none";
  if (ring === "live") {
    ringBg = "linear-gradient(90deg, #E8444E, #FFA94D, #FFD83A, #E8444E)";
    ringBg += "";
    ringAnimation = "storyRingSpin 2.6s linear infinite";
  } else if (ring === "story") {
    ringBg = "linear-gradient(90deg, #FFD83A, #FFA94D, #E8444E, #9F7AEA, #FFD83A)";
    ringAnimation = "storyRingSpin 8s linear infinite";
  }
  return (
    <div className="relative flex-shrink-0" style={{ width: size, height: size }}>
      <div
        className="rounded-full flex items-center justify-center"
        style={{
          width: size, height: size,
          background: ring === "none" ? "transparent" : ringBg,
          backgroundSize: "200% 100%",
          animation: ringAnimation,
          padding,
        }}
      >
        <div
          className="rounded-full flex items-center justify-center font-display font-bold"
          style={{
            width: inner, height: inner,
            background: `radial-gradient(circle at 30% 28%, ${user.avatarColor} 0%, ${user.avatarColor}D0 100%)`,
            color: "white",
            fontSize: Math.round(inner * 0.42),
            border: ring === "none" ? "none" : "2.5px solid white",
            boxShadow: "inset 0 2px 0 rgba(255,255,255,0.28), 0 2px 0 rgba(0,0,0,0.1)",
            letterSpacing: "-0.02em",
          }}
        >
          {user.displayName.charAt(0)}
        </div>
      </div>
      {/* Online dot */}
      {user.online && ring !== "live" && (
        <div
          className="absolute rounded-full"
          style={{
            bottom: 0, right: 0,
            width: Math.max(10, size * 0.22), height: Math.max(10, size * 0.22),
            background: "linear-gradient(180deg, #5BE890 0%, #3A9560 100%)",
            border: "2.5px solid white",
            boxShadow: "0 0 8px rgba(91,200,144,0.6)",
          }}
        />
      )}
      {/* Country flag chip */}
      {showCountry && (
        <div
          className="absolute rounded-full flex items-center justify-center"
          style={{
            top: -2, right: -4,
            width: Math.max(16, size * 0.32), height: Math.max(16, size * 0.32),
            background: "white",
            border: "2px solid white",
            fontSize: Math.max(10, size * 0.22),
            boxShadow: "0 1px 4px rgba(0,0,0,0.18)",
            lineHeight: 1,
          }}
        >
          {user.country}
        </div>
      )}
    </div>
  );
};



/* ============================================================
   SOCIAL — DOPAMINE PASS
   Rule: each individual element is JUICY, but each screen does
   ONE thing. No competing sections. Just rich, fun cards within
   a clean structure. CTAs are big and pressable. Pufflings are
   shown like collectible character cards.
   ============================================================ */

/* Warm background — 2 subtle sparkles, not the swarm of before */
// ============================================================================
// SOCIAL TAB — refreshed sky/teal visual design (Feed / Ranks / unified Profile,
// people-search modal, and a Challenge modal where the challenger picks WHICH of
// their pufflings is sent in). Shares MOCK_USERS / SOCIAL_FEED / LANGUAGES /
// BELT_ORDER / Puffling / MiniBelt / UserAvatar / formatTimeAgo with the app.
// Live-duel only — the old async/ghost/drill duel modes were scrapped.
// ============================================================================
const CloudPuff = ({ width = 48 }) => (
  <svg width={width} height={width * 0.55} viewBox="0 0 100 55" fill="none" aria-hidden>
    <ellipse cx="30" cy="35" rx="22" ry="16" fill="rgba(255,255,255,0.95)" />
    <ellipse cx="58" cy="26" rx="28" ry="20" fill="rgba(255,255,255,0.95)" />
    <ellipse cx="78" cy="38" rx="18" ry="14" fill="rgba(255,255,255,0.95)" />
  </svg>
);

// The Social screens' scroll container. The sky + clouds backdrop is now a
// single PERSISTENT layer shared with Home (see PersistentSky), so this is
// transparent and only provides the scroll viewport. `variant` is kept for
// call-site compatibility but no longer drives any decor.
const SocialBg = ({ children, variant = "feed" }) => (
  <div className="relative w-full h-full overflow-y-auto no-scrollbar" style={{ background: "transparent" }}>
    {children}
  </div>
);

// One sky-and-clouds backdrop shared by the Home + Social screens. Rendered
// ONCE behind those screens (which are transparent) and kept mounted as you
// move between Home / Feed / Ranks / Me, so the clouds keep a single steady
// drift instead of jumping or restarting on every navigation. pointer-events
// are off so it never intercepts taps, and it sits behind content by DOM order.
const PersistentSky = () => (
  <div
    className="absolute inset-0 pointer-events-none"
    style={{ background: "linear-gradient(180deg, #4BBCF0 0%, #6BCFE8 28%, #9BDFC8 52%, #4ABF96 76%, #1A8F6E 100%)" }}
  >
    <div className="absolute cloud-float-a" style={{ top: "9%",  left: 14,  opacity: 0.78 }}><CloudPuff width={66} /></div>
    <div className="absolute cloud-float-b" style={{ top: "17%", right: 18, opacity: 0.6 }}><CloudPuff width={48} /></div>
    <div className="absolute cloud-float-c" style={{ top: "31%", left: 26, opacity: 0.5 }}><CloudPuff width={40} /></div>
    <div className="absolute cloud-float-d" style={{ top: "45%", right: 26, opacity: 0.42 }}><CloudPuff width={54} /></div>
    <div className="absolute sparkle" style={{ top: "13%", right: "26%", fontSize: 13, color: "#FFD83A" }}>✦</div>
    <div className="absolute sparkle" style={{ top: "25%", left: "20%",  fontSize: 10, color: "#FFFFFF", animationDelay: "1.1s" }}>✦</div>
    <div className="absolute sparkle" style={{ top: "39%", right: "16%", fontSize: 11, color: "#FFFFFF", animationDelay: "1.9s" }}>✦</div>
  </div>
);

const SocialHeader = ({ title, onBack, onSearch, rightSlot, onBell, bellCount = 0 }) => (
  <div className="flex items-center justify-between px-2 pt-1 mb-2">
    <button
      onClick={onBack}
      className="rounded-full flex items-center justify-center tactile"
      style={{
        width: 38, height: 38,
        background: "white",
        color: "#1A1E3C",
        fontSize: 18, fontWeight: 700,
        border: "1.5px solid rgba(26,30,60,0.12)",
        boxShadow: "0 2px 0 rgba(26,30,60,0.18)",
      }}
    >
      ←
    </button>
    <div className="font-display font-bold" style={{
      fontSize: 22,
      color: "#FFFFFF",
      letterSpacing: "-0.02em",
      textShadow: "0 0 10px rgba(26,30,60,0.55), 0 2px 0 rgba(26,30,60,0.35)",
    }}>
      {title}
    </div>
    <div className="flex items-center gap-2">
      {onBell && (
        <button
          onClick={onBell}
          aria-label="Notifications"
          className="relative rounded-full flex items-center justify-center tactile"
          style={{ width: 38, height: 38, background: "white", fontSize: 16, border: "1.5px solid rgba(26,30,60,0.12)", boxShadow: "0 2px 0 rgba(26,30,60,0.18)" }}
        >
          🔔
          {bellCount > 0 && (
            <span
              className="absolute font-display font-bold flex items-center justify-center"
              style={{ top: -4, right: -4, minWidth: 17, height: 17, padding: "0 4px", fontSize: 9.5, lineHeight: 1, color: "white", background: "#E8444E", border: "1.5px solid white", borderRadius: 999, fontVariantNumeric: "tabular-nums" }}
            >
              {bellCount}
            </span>
          )}
        </button>
      )}
      {onSearch ? (
        <button
          onClick={onSearch}
          aria-label="Search people"
          className="rounded-full flex items-center justify-center tactile"
          style={{
            width: 38, height: 38,
            background: "white",
            fontSize: 16,
            border: "1.5px solid rgba(26,30,60,0.12)",
            boxShadow: "0 2px 0 rgba(26,30,60,0.18)",
          }}
        >
          🔍
        </button>
      ) : (
        <div style={{ width: 38 }}>{rightSlot}</div>
      )}
    </div>
  </div>
);

const SocialTabs = ({ active, onChange }) => {
  const tabs = [
    { id: "feed",   label: "Feed"   },
    { id: "ranks",  label: "Ranks"  },
    { id: "me",     label: "Me"     },
  ];
  return (
    <div className="flex items-center gap-1.5 px-1 mb-4">
      {tabs.map((t) => {
        const isActive = active === t.id;
        return (
          <button
            key={t.id}
            onClick={() => onChange(t.id)}
            className="tactile flex-1 rounded-full"
            style={{
              padding: "9px 4px",
              background: isActive
                ? "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)"
                : "rgba(255,255,255,0.7)",
              border: `1.5px solid ${isActive ? "#B85020" : "rgba(122,90,32,0.12)"}`,
              boxShadow: isActive
                ? "0 3px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.45)"
                : "0 1.5px 0 rgba(122,90,32,0.08)",
              color: isActive ? "#3D2A05" : "#7A5A20",
              fontSize: 13,
              fontWeight: 800,
              letterSpacing: "0.02em",
            }}
          >
            {t.label}
          </button>
        );
      })}
    </div>
  );
};

const FeedCard = ({ item, onViewUser, userById }) => {
  const user = userById(item.userId);
  if (!user) return null;
  const puff = user.pufflings[item.pufflingIdx];
  const lang = LANGUAGES[puff.lang];

  const types = {
    newBelt: {
      icon: "🏆",
      bg: "linear-gradient(180deg, #FFFFFF 0%, #FFF1D0 100%)",
      badgeBg: "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)",
      border: "rgba(184,80,32,0.25)",
      shadow: "0 3px 0 rgba(184,80,32,0.12), 0 6px 14px rgba(255,169,77,0.18)",
      verb: <>earned <b style={{ color: "#E87822" }}>{item.detail?.newBelt?.charAt(0).toUpperCase() + item.detail?.newBelt?.slice(1)} Belt</b></>,
      big: true,
    },
    victory: {
      icon: "⚔️",
      bg: "linear-gradient(180deg, #FFFFFF 0%, #E8F8EE 100%)",
      badgeBg: "linear-gradient(180deg, #C3F0D0 0%, #5BC890 100%)",
      border: "rgba(74,160,120,0.25)",
      shadow: "0 2px 0 rgba(74,160,120,0.1), 0 4px 12px rgba(91,200,144,0.12)",
      verb: <>KO'd <b>{item.detail?.oppName}</b></>,
    },
    duelWon: {
      icon: "👊",
      bg: "linear-gradient(180deg, #FFFFFF 0%, #FFF0EE 100%)",
      badgeBg: "linear-gradient(180deg, #FFB3A8 0%, #E8444E 100%)",
      border: "rgba(168,37,48,0.22)",
      shadow: "0 2px 0 rgba(168,37,48,0.12), 0 4px 12px rgba(232,68,78,0.12)",
      verb: <>won a duel vs <b>{userById(item.detail?.vsUser)?.displayName || "rival"}</b></>,
    },
    streak: {
      icon: "🔥",
      bg: "linear-gradient(180deg, #FFFFFF 0%, #FFF3E0 100%)",
      badgeBg: "linear-gradient(180deg, #FFC07A 0%, #FFA94D 100%)",
      border: "rgba(224,130,46,0.22)",
      shadow: "0 2px 0 rgba(224,130,46,0.12), 0 4px 12px rgba(255,169,77,0.15)",
      verb: <><b style={{ color: "#E87822" }}>{item.detail?.days}-day streak</b></>,
    },
    newPuffling: {
      icon: "🐣",
      bg: "linear-gradient(180deg, #FFFFFF 0%, #F2E8FB 100%)",
      badgeBg: "linear-gradient(180deg, #B69AE8 0%, #9F7AEA 100%)",
      border: "rgba(122,82,181,0.22)",
      shadow: "0 2px 0 rgba(122,82,181,0.12), 0 4px 12px rgba(159,122,234,0.12)",
      verb: <>hatched <b>{puff.name}</b></>,
    },
  };
  const t = types[item.type] || types.victory;

  return (
    <button
      onClick={() => onViewUser(user.id)}
      className="tactile rounded-2xl flex items-center gap-3 text-left"
      style={{
        padding: "12px 13px",
        background: t.bg,
        border: `1.5px solid ${t.border}`,
        boxShadow: t.shadow,
      }}
    >
      <UserAvatar user={user} size={44} ring="none" />
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1 flex-wrap" style={{ lineHeight: 1.25 }}>
          <span className="font-display font-bold" style={{ fontSize: 14, color: "#3D2A05", letterSpacing: "-0.005em" }}>
            {user.displayName}
          </span>
          <span className="font-body" style={{ fontSize: 13.5, color: "#3D2A05" }}>
            {t.verb}
          </span>
        </div>
        <div className="flex items-center gap-1.5 mt-1" style={{ fontSize: 11, color: "rgba(58,42,5,0.55)" }}>
          <span>{lang.flag}</span>
          <span className="font-body font-bold uppercase" style={{ letterSpacing: "0.08em", fontSize: 9 }}>{lang.name}</span>
          <span style={{ opacity: 0.4 }}>·</span>
          <span className="font-body">{formatTimeAgo(item.minutesAgo)}</span>
        </div>
      </div>
      <div
        className="flex-shrink-0 rounded-xl flex items-center justify-center"
        style={{
          width: t.big ? 44 : 36, height: t.big ? 44 : 36,
          background: t.badgeBg,
          boxShadow: "inset 0 1px 0 rgba(255,255,255,0.4), 0 2px 0 rgba(0,0,0,0.08)",
          fontSize: t.big ? 22 : 18,
        }}
      >
        {t.icon}
      </div>
    </button>
  );
};

const NotificationsPanel = ({ requests, notifications, onAccept, onDecline, onViewUser, onClose }) => {
  const resolve = (id) => ALL_SOCIAL_USERS.find((u) => u.id === id);
  const noteText = (n) => {
    const u = resolve(n.userId);
    const name = u?.displayName || "Someone";
    if (n.kind === "record") return `${name} beat your recall record`;
    if (n.kind === "league") return `${name} climbed to a new league`;
    return `${name} started learning a new language`;
  };
  const noteIcon = (kind) => (kind === "record" ? "🏅" : kind === "league" ? "🛡️" : "🌱");
  const reqUsers = requests.map((r) => ({ ...r, user: resolve(r.userId) })).filter((r) => r.user);

  return (
    <div className="absolute inset-0" style={{ zIndex: 70, background: "rgba(10,20,40,0.5)" }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        className="absolute left-0 right-0 top-0 flex flex-col"
        style={{ maxHeight: "100%", background: "linear-gradient(180deg, #FFFFFF 0%, #F4F7FB 100%)", borderBottomLeftRadius: 26, borderBottomRightRadius: 26, boxShadow: "0 18px 44px rgba(10,20,40,0.35)", animation: "slideUp 0.3s cubic-bezier(0.2,0.8,0.2,1) both" }}
      >
        <div className="flex items-center justify-between px-5 pt-5 pb-3 flex-shrink-0">
          <div className="font-display font-bold" style={{ fontSize: 20, color: "#1A1E3C" }}>Notifications</div>
          <button onClick={onClose} className="tactile rounded-full flex items-center justify-center" style={{ width: 32, height: 32, background: "rgba(26,30,60,0.06)", color: "#1A1E3C", fontSize: 15 }} aria-label="Close">✕</button>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar px-4 pb-5" style={{ minHeight: 0 }}>
          {reqUsers.length === 0 && notifications.length === 0 && (
            <div className="text-center py-12 font-body" style={{ fontSize: 13, color: "rgba(26,30,60,0.4)" }}>You're all caught up 🎉</div>
          )}

          {reqUsers.length > 0 && (
            <>
              <div className="font-body font-bold uppercase px-1 mb-2 mt-1" style={{ fontSize: 10, letterSpacing: "0.14em", color: "rgba(26,30,60,0.45)" }}>Friend requests</div>
              {reqUsers.map((r) => (
                <div key={r.id} className="flex items-center gap-3 rounded-2xl mb-2" style={{ padding: "10px 12px", background: "white", border: "1.5px solid rgba(26,30,60,0.1)", boxShadow: "0 1px 0 rgba(26,30,60,0.05)" }}>
                  <button onClick={() => onViewUser(r.user.id)} className="tactile flex items-center gap-3 flex-1 min-w-0 text-left">
                    <UserAvatar user={r.user} size={42} showCountry />
                    <div className="min-w-0">
                      <div className="font-display font-bold truncate" style={{ fontSize: 14, color: "#1A1E3C" }}>{r.user.displayName}</div>
                      <div className="font-body truncate" style={{ fontSize: 10.5, color: "rgba(26,30,60,0.5)" }}>
                        {r.mutuals > 0 ? `${r.mutuals} mutual friend${r.mutuals > 1 ? "s" : ""} · ` : ""}{formatTimeAgo(r.minutesAgo)}
                      </div>
                    </div>
                  </button>
                  <button onClick={() => onDecline(r.id)} className="tactile flex-shrink-0 rounded-xl font-display font-bold" style={{ padding: "8px 11px", fontSize: 12, color: "rgba(26,30,60,0.6)", background: "rgba(26,30,60,0.06)" }}>Decline</button>
                  <button onClick={() => onAccept(r.id)} className="tactile flex-shrink-0 rounded-xl font-display font-bold" style={{ padding: "8px 14px", fontSize: 12, color: "white", background: "linear-gradient(180deg,#3DBA8C,#1A8F6E)", border: "1.5px solid #0F6650", boxShadow: "0 2px 0 #0F6650" }}>Accept</button>
                </div>
              ))}
            </>
          )}

          {notifications.length > 0 && (
            <>
              <div className="font-body font-bold uppercase px-1 mb-2 mt-4" style={{ fontSize: 10, letterSpacing: "0.14em", color: "rgba(26,30,60,0.45)" }}>Earlier</div>
              {notifications.map((n) => {
                const u = resolve(n.userId);
                return (
                  <button key={n.id} onClick={() => u && onViewUser(u.id)} className="tactile w-full flex items-center gap-3 rounded-2xl mb-2 text-left" style={{ padding: "10px 12px", background: "rgba(255,255,255,0.65)", border: "1.5px solid rgba(26,30,60,0.07)" }}>
                    {u && <UserAvatar user={u} size={36} />}
                    <div className="flex-1 min-w-0">
                      <div className="font-body font-bold" style={{ fontSize: 12.5, color: "#1A1E3C", lineHeight: 1.3 }}>
                        <span style={{ marginRight: 5 }}>{noteIcon(n.kind)}</span>{noteText(n)}
                      </div>
                      <div className="font-body" style={{ fontSize: 10, color: "rgba(26,30,60,0.45)" }}>{formatTimeAgo(n.minutesAgo)}</div>
                    </div>
                  </button>
                );
              })}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

const SocialFeedScreen = ({ activeTab, onTabChange, onViewUser, onBack, onOpenSearch, challengerCount = 0, onOpenChallengers, onBell, bellCount = 0 }) => {
  const userById = (id) => MOCK_USERS.find((u) => u.id === id);
  return (
    <SocialBg variant="feed">
      <div className="relative flex flex-col px-3 pt-3 pb-5" style={{ minHeight: "100%" }}>
        <SocialHeader title="Social" onBack={onBack} onSearch={onOpenSearch} onBell={onBell} bellCount={bellCount} />
        <SocialTabs active={activeTab} onChange={onTabChange} />

        {/* Challengers clout banner — people waiting to fight you */}
        {challengerCount > 0 && (
          <button
            onClick={onOpenChallengers}
            className="tactile w-full rounded-2xl flex items-center gap-3 mb-3"
            style={{ padding: "11px 14px", background: "linear-gradient(180deg, #FF6B6B 0%, #C53030 100%)", border: "2px solid #7A1F1F", boxShadow: "0 3px 0 #7A1F1F" }}
          >
            <span style={{ fontSize: 22 }}>⚔️</span>
            <div className="flex-1 text-left">
              <div className="font-display font-bold" style={{ fontSize: 14, color: "white", textShadow: "0 1px 0 rgba(0,0,0,0.25)" }}>
                {challengerCount} {challengerCount === 1 ? "challenger is" : "challengers are"} waiting
              </div>
              <div className="font-body" style={{ fontSize: 10.5, color: "rgba(255,255,255,0.85)" }}>Tap to see who wants to fight you</div>
            </div>
            <span className="font-display font-bold" style={{ fontSize: 18, color: "white" }}>→</span>
          </button>
        )}

        <div className="px-2 mb-3 flex items-baseline justify-between">
          <h2 className="font-display font-bold flex items-center gap-2" style={{
            fontSize: 18,
            color: "#FFFFFF",
            letterSpacing: "-0.015em",
            textShadow: "0 0 10px rgba(26,30,60,0.55), 0 2px 0 rgba(26,30,60,0.35)",
          }}>
            <span>📜</span>
            <span>Activity</span>
          </h2>
          <span className="font-body font-bold uppercase" style={{
            fontSize: 9,
            color: "rgba(255,255,255,0.9)",
            letterSpacing: "0.14em",
            textShadow: "0 0 6px rgba(26,30,60,0.5), 0 1px 1px rgba(26,30,60,0.35)",
          }}>
            Last 48h
          </span>
        </div>

        <div className="flex flex-col gap-2 px-0.5">
          {SOCIAL_FEED.map((item, i) => (
            <FeedCard key={item.id} item={item} index={i} onViewUser={onViewUser} userById={userById} />
          ))}
        </div>
      </div>
    </SocialBg>
  );
};

const LeaderboardView = ({ scope, onScopeChange, onViewUser }) => {
  // Build the leaderboard. Friends = you + your friends. Global = everyone.
  const pool = scope === "friends"
    ? MOCK_USERS
    : [...MOCK_USERS, ...GLOBAL_FIGHTERS];
  const ranked = [...pool].sort((a, b) => b.weeklyRecallReps - a.weeklyRecallReps);
  const myRank = ranked.findIndex((u) => u.id === "me") + 1;
  const topRep = ranked[0]?.weeklyRecallReps || 1;

  // Split into podium (top 3) and rest
  const podium = ranked.slice(0, 3);
  const rest = ranked.slice(3);
  // Re-order podium for display: silver(2), gold(1), bronze(3) — classic Mario Kart layout
  const podiumLayout = podium.length >= 3
    ? [podium[1], podium[0], podium[2]]
    : podium;

  return (
    <>
      {/* Title + countdown */}
      <div className="px-2 mb-1 flex items-baseline justify-between">
        <h2 className="font-display font-bold flex items-center gap-2" style={{
          fontSize: 18,
          color: "#FFFFFF",
          letterSpacing: "-0.015em",
          textShadow: "0 0 10px rgba(26,30,60,0.55), 0 2px 0 rgba(26,30,60,0.35)",
        }}>
          <span>🏆</span>
          <span>This Week's Ranks</span>
        </h2>
      </div>
      <div className="px-2 mb-3 flex items-center gap-1.5 font-body" style={{
        fontSize: 11,
        color: "rgba(255,255,255,0.9)",
        textShadow: "0 0 6px rgba(26,30,60,0.5), 0 1px 1px rgba(26,30,60,0.35)",
      }}>
        <span style={{ fontSize: 12 }}>🥋</span>
        <span>Most Recall reps this week</span>
        <span style={{ opacity: 0.4 }}>·</span>
        <span className="font-bold" style={{ color: "#FFE066" }}>Resets in 3d 14h</span>
      </div>

      {/* Scope toggle: Friends ⇄ Global */}
      <div className="flex items-center gap-1.5 mx-1 mb-4 rounded-full"
        style={{
          padding: 3,
          background: "rgba(255,255,255,0.55)",
          border: "1px solid rgba(26,30,60,0.1)",
          backdropFilter: "blur(8px)",
          WebkitBackdropFilter: "blur(8px)",
        }}
      >
        <button
          onClick={() => onScopeChange("friends")}
          className="tactile flex-1 rounded-full flex items-center justify-center gap-1.5"
          style={{
            padding: "7px 6px",
            background: scope === "friends" ? "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)" : "transparent",
            color: scope === "friends" ? "#3D2A05" : "#1A1E3C",
            fontSize: 11.5,
            fontWeight: 800,
            letterSpacing: "0.04em",
            boxShadow: scope === "friends" ? "0 2px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.45)" : "none",
            border: scope === "friends" ? "1.5px solid #B85020" : "1.5px solid transparent",
          }}
        >
          <span style={{ fontSize: 12 }}>🤝</span>
          <span>Friends</span>
        </button>
        <button
          onClick={() => onScopeChange("global")}
          className="tactile flex-1 rounded-full flex items-center justify-center gap-1.5"
          style={{
            padding: "7px 6px",
            background: scope === "global" ? "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)" : "transparent",
            color: scope === "global" ? "#3D2A05" : "#1A1E3C",
            fontSize: 11.5,
            fontWeight: 800,
            letterSpacing: "0.04em",
            boxShadow: scope === "global" ? "0 2px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.45)" : "none",
            border: scope === "global" ? "1.5px solid #B85020" : "1.5px solid transparent",
          }}
        >
          <span style={{ fontSize: 12 }}>🌍</span>
          <span>Global</span>
        </button>
      </div>

      {/* PODIUM — top 3 in Mario Kart layout (silver L, gold center, bronze R) */}
      <div className="flex items-end justify-center gap-2 mb-4 px-1" style={{ minHeight: 200 }}>
        {podiumLayout.map((user, displayIdx) => {
          // Map display position back to actual rank
          const actualRank = podiumLayout.length === 3
            ? (displayIdx === 0 ? 2 : displayIdx === 1 ? 1 : 3)
            : displayIdx + 1;
          const medals = { 1: "🥇", 2: "🥈", 3: "🥉" };
          const heights = { 1: 96, 2: 76, 3: 64 };
          const colors = {
            1: { grad: "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)", border: "#B85020", shadow: "0 4px 0 #B85020" },
            2: { grad: "linear-gradient(180deg, #E8E8E8 0%, #B0B0B0 100%)", border: "#7A7A7A", shadow: "0 4px 0 #7A7A7A" },
            3: { grad: "linear-gradient(180deg, #DAA060 0%, #8B5A2B 100%)", border: "#6A3F1A", shadow: "0 4px 0 #6A3F1A" },
          };
          const c = colors[actualRank];
          return (
            <button
              key={user.id}
              onClick={() => onViewUser(user.id)}
              className="tactile flex-1 flex flex-col items-center"
              style={{ maxWidth: 110 }}
            >
              {/* Avatar with medal */}
              <div className="relative" style={{ marginBottom: 8 }}>
                <div
                  className="rounded-full flex items-center justify-center"
                  style={{
                    width: actualRank === 1 ? 70 : 58,
                    height: actualRank === 1 ? 70 : 58,
                    background: c.grad,
                    padding: 3,
                    boxShadow: actualRank === 1
                      ? "0 4px 14px rgba(255,169,77,0.5), 0 0 24px rgba(255,216,58,0.4)"
                      : "0 3px 10px rgba(0,0,0,0.18)",
                  }}
                >
                  <div className="rounded-full overflow-hidden" style={{ width: "100%", height: "100%" }}>
                    <div
                      className="rounded-full flex items-center justify-center font-display font-bold"
                      style={{
                        width: "100%", height: "100%",
                        background: `radial-gradient(circle at 30% 28%, ${user.avatarColor} 0%, ${user.avatarColor}D0 100%)`,
                        color: "white",
                        fontSize: actualRank === 1 ? 28 : 24,
                        border: "2.5px solid white",
                      }}
                    >
                      {user.displayName.charAt(0)}
                    </div>
                  </div>
                </div>
                {/* Medal */}
                <div className="absolute" style={{
                  top: actualRank === 1 ? -8 : -6,
                  right: actualRank === 1 ? -8 : -6,
                  fontSize: actualRank === 1 ? 26 : 22,
                  filter: "drop-shadow(0 2px 3px rgba(0,0,0,0.25))",
                }}>
                  {medals[actualRank]}
                </div>
              </div>
              {/* Name */}
              <div className="font-display font-bold text-center" style={{
                fontSize: actualRank === 1 ? 13.5 : 12,
                color: "#3D2A05",
                lineHeight: 1.05,
                letterSpacing: "-0.005em",
              }}>
                {user.displayName} {user.id === "me" && <span style={{ color: "#E87822" }}>(you)</span>}
              </div>
              <div className="font-body" style={{ fontSize: 10, color: "rgba(58,42,5,0.5)", marginTop: 1 }}>
                {user.country}
              </div>
              {/* Podium block */}
              <div
                className="w-full rounded-t-2xl flex flex-col items-center justify-center mt-2"
                style={{
                  height: heights[actualRank],
                  background: c.grad,
                  border: `1.5px solid ${c.border}`,
                  borderBottom: "none",
                  boxShadow: "inset 0 1px 0 rgba(255,255,255,0.4)",
                  paddingTop: 6,
                }}
              >
                <div className="font-display font-bold" style={{
                  fontSize: actualRank === 1 ? 22 : 18,
                  color: "#3D2A05",
                  fontVariantNumeric: "tabular-nums",
                  letterSpacing: "-0.01em",
                  textShadow: "0 1px 0 rgba(255,255,255,0.4)",
                }}>
                  {user.weeklyRecallReps.toLocaleString()}
                </div>
                <div className="font-body font-bold uppercase" style={{
                  fontSize: 8.5,
                  color: "#7A2D0A",
                  letterSpacing: "0.14em",
                  marginTop: -2,
                }}>
                  reps
                </div>
              </div>
            </button>
          );
        })}
      </div>

      {/* Rest of the rankings */}
      {rest.length > 0 && (
        <div className="flex flex-col gap-1.5 px-0.5">
          {rest.map((user, i) => {
            const rank = i + 4;
            const isMe = user.id === "me";
            const pct = Math.round((user.weeklyRecallReps / topRep) * 100);
            return (
              <button
                key={user.id}
                onClick={() => onViewUser(user.id)}
                className="tactile rounded-2xl flex items-center gap-3 text-left relative overflow-hidden"
                style={{
                  padding: "10px 12px",
                  background: isMe
                    ? "linear-gradient(180deg, #FFF1D0 0%, #FFE89A 100%)"
                    : "linear-gradient(180deg, #FFFFFF 0%, #FFFBEF 100%)",
                  border: `1.5px solid ${isMe ? "#B85020" : "rgba(122,90,32,0.1)"}`,
                  boxShadow: isMe
                    ? "0 3px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.5)"
                    : "0 1.5px 0 rgba(122,90,32,0.06)",
                }}
              >
                {/* Subtle progress bar in background showing relative reps */}
                <div
                  className="absolute inset-y-0 left-0 pointer-events-none"
                  style={{
                    width: `${pct}%`,
                    background: isMe
                      ? "linear-gradient(90deg, rgba(255,169,77,0.18) 0%, rgba(255,169,77,0) 100%)"
                      : "linear-gradient(90deg, rgba(255,224,102,0.25) 0%, rgba(255,224,102,0) 100%)",
                  }}
                />
                {/* Rank number */}
                <div
                  className="flex-shrink-0 rounded-full flex items-center justify-center font-display font-bold relative"
                  style={{
                    width: 28, height: 28,
                    background: isMe ? "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)" : "rgba(122,90,32,0.1)",
                    color: isMe ? "#3D2A05" : "rgba(58,42,5,0.7)",
                    fontSize: 12,
                    fontVariantNumeric: "tabular-nums",
                    border: isMe ? "1.5px solid #B85020" : "none",
                  }}
                >
                  {rank}
                </div>
                <div className="relative flex-shrink-0">
                  <UserAvatar user={user} size={38} ring="none" />
                </div>
                <div className="flex-1 min-w-0 relative">
                  <div className="flex items-center gap-1" style={{ lineHeight: 1.15 }}>
                    <span className="font-display font-bold" style={{ fontSize: 14, color: "#3D2A05", letterSpacing: "-0.005em" }}>
                      {user.displayName}
                    </span>
                    <span style={{ fontSize: 12, marginLeft: 2 }}>{user.country}</span>
                    {isMe && (
                      <span className="font-body font-bold uppercase rounded-full ml-1" style={{
                        fontSize: 8.5,
                        color: "#7A2D0A",
                        letterSpacing: "0.12em",
                        padding: "1px 7px",
                        background: "rgba(255, 224, 102, 0.6)",
                        border: "1px solid rgba(184,80,32,0.3)",
                      }}>
                        You
                      </span>
                    )}
                  </div>
                  <div className="font-body" style={{ fontSize: 10.5, color: "rgba(58,42,5,0.5)", marginTop: 1 }}>
                    @{user.username}
                  </div>
                </div>
                <div className="text-right relative">
                  <div className="font-display font-bold" style={{
                    fontSize: 15,
                    color: "#3D2A05",
                    fontVariantNumeric: "tabular-nums",
                    lineHeight: 1,
                    letterSpacing: "-0.01em",
                  }}>
                    {user.weeklyRecallReps.toLocaleString()}
                  </div>
                  <div className="font-body font-bold uppercase" style={{
                    fontSize: 8,
                    color: "rgba(58,42,5,0.55)",
                    letterSpacing: "0.12em",
                    marginTop: 2,
                  }}>
                    reps
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      )}

      {/* If "me" is not in podium and not in shown list, pin a "your rank" footer */}
      {myRank > 3 && rest.findIndex((u) => u.id === "me") === -1 && (
        <div className="mt-4 mx-0.5">
          <div className="font-body font-bold uppercase text-center" style={{ fontSize: 9, color: "rgba(58,42,5,0.5)", letterSpacing: "0.14em", marginBottom: 6 }}>
            Your Rank
          </div>
          <div
            className="rounded-2xl flex items-center gap-3 px-3 py-2.5"
            style={{
              background: "linear-gradient(180deg, #FFF1D0 0%, #FFE89A 100%)",
              border: "1.5px solid #B85020",
              boxShadow: "0 3px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.5)",
            }}
          >
            <div className="font-display font-bold rounded-full flex items-center justify-center flex-shrink-0"
              style={{ width: 28, height: 28, background: "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)", color: "#3D2A05", fontSize: 12, border: "1.5px solid #B85020" }}
            >
              {myRank}
            </div>
            <UserAvatar user={MOCK_USERS[0]} size={38} ring="none" />
            <div className="flex-1">
              <div className="font-display font-bold" style={{ fontSize: 14, color: "#3D2A05" }}>You</div>
              <div className="font-body" style={{ fontSize: 10.5, color: "rgba(58,42,5,0.55)", marginTop: 1 }}>
                Keep grinding to climb the ranks 💪
              </div>
            </div>
            <div className="font-display font-bold" style={{ fontSize: 15, color: "#3D2A05", fontVariantNumeric: "tabular-nums" }}>
              {MOCK_USERS[0].weeklyRecallReps.toLocaleString()}
            </div>
          </div>
        </div>
      )}
    </>
  );
};

const SocialRanksScreen = ({ activeTab, onTabChange, onViewUser, onBack, onOpenSearch, onBell, bellCount = 0 }) => {
  // Default to Friends scope since that's the most personally engaging
  // — the player can see themselves alongside people they know.
  const [scope, setScope] = useState("friends");
  return (
    <SocialBg variant="ranks">
      <div className="relative flex flex-col px-3 pt-3 pb-5" style={{ minHeight: "100%" }}>
        <SocialHeader title="Social" onBack={onBack} onSearch={onOpenSearch} onBell={onBell} bellCount={bellCount} />
        <SocialTabs active={activeTab} onChange={onTabChange} />
        <LeaderboardView scope={scope} onScopeChange={setScope} onViewUser={onViewUser} />
      </div>
    </SocialBg>
  );
};

/* Search result row */
const SearchRow = ({ user, onView }) => {
  const headline = [...user.pufflings].sort((a, b) => b.victories - a.victories)[0];
  const lang = LANGUAGES[headline.lang];
  return (
    <button
      onClick={onView}
      className="tactile rounded-2xl flex items-center gap-3 text-left"
      style={{
        padding: "11px 14px 11px 12px",
        background: "linear-gradient(180deg, #FFFFFF 0%, #FFFBEF 100%)",
        border: "1.5px solid rgba(122,90,32,0.12)",
        boxShadow: "0 2px 0 rgba(122,90,32,0.06)",
      }}
    >
      <UserAvatar user={user} size={44} ring="none" />
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-1" style={{ lineHeight: 1.15 }}>
          <span className="font-display font-bold" style={{ fontSize: 14, color: "#3D2A05" }}>{user.displayName}</span>
          <span style={{ fontSize: 12, marginLeft: 2 }}>{user.country}</span>
        </div>
        <div className="flex items-center gap-1.5 mt-0.5" style={{ fontSize: 11, color: "rgba(58,42,5,0.55)" }}>
          <span className="font-body">@{user.username}</span>
          <span style={{ opacity: 0.4 }}>·</span>
          <MiniBelt belt={headline.belt} width={18} height={7} />
          <span>{lang.flag}</span>
        </div>
      </div>
      <span style={{ fontSize: 18, color: "rgba(58,42,5,0.3)" }}>›</span>
    </button>
  );
};

const PeopleSearchModal = ({ onClose, onViewUser }) => {
  const [query, setQuery] = useState("");
  const inputRef = useRef(null);
  useEffect(() => {
    const t = setTimeout(() => { if (inputRef.current) inputRef.current.focus(); }, 140);
    return () => clearTimeout(t);
  }, []);

  const q = query.trim().toLowerCase();
  const all = MOCK_USERS.filter((u) => u.id !== "me");
  const results = q === ""
    ? null
    : all.filter((u) => u.username.toLowerCase().includes(q) || u.displayName.toLowerCase().includes(q));
  const suggestions = [...all]
    .map((u) => ({ ...u, totalVictories: u.pufflings.reduce((s, p) => s + p.victories, 0) }))
    .sort((a, b) => b.totalVictories - a.totalVictories)
    .slice(0, 5);

  return (
    <div className="absolute inset-0 z-50 flex flex-col">
      {/* Dim backdrop */}
      <div
        className="absolute inset-0"
        style={{ background: "rgba(26,30,60,0.45)" }}
        onClick={onClose}
      />
      {/* Panel slides down from the top, full height */}
      <div
        className="relative flex flex-col"
        style={{
          height: "100%",
          background: "linear-gradient(180deg, #FFFFFF 0%, #FBF1DC 100%)",
          animation: "searchSheetIn 0.26s cubic-bezier(0.22,1,0.36,1)",
        }}
      >
        {/* Search bar row */}
        <div className="flex items-center gap-2 px-3 pt-4 pb-3" style={{ borderBottom: "1.5px solid rgba(122,90,32,0.1)" }}>
          <div
            className="flex-1 flex items-center gap-2 rounded-full"
            style={{
              padding: "11px 14px",
              background: "white",
              border: "1.5px solid rgba(122,90,32,0.18)",
              boxShadow: "0 2px 0 rgba(122,90,32,0.06)",
            }}
          >
            <span style={{ fontSize: 15 }}>🔍</span>
            <input
              ref={inputRef}
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Find duelists by name or @username"
              className="flex-1 bg-transparent outline-none font-body"
              style={{ fontSize: 14, color: "#3D2A05" }}
            />
            {query && (
              <button
                onClick={() => setQuery("")}
                className="rounded-full flex items-center justify-center tactile"
                style={{ width: 22, height: 22, background: "rgba(58,42,5,0.1)", color: "#5A3A1A", fontSize: 11, fontWeight: 700, lineHeight: 1 }}
              >
                ✕
              </button>
            )}
          </div>
          <button
            onClick={onClose}
            className="tactile font-display font-bold"
            style={{ fontSize: 14, color: "#1A8F6E", padding: "4px 6px" }}
          >
            Cancel
          </button>
        </div>

        {/* Results / trending */}
        <div className="flex-1 overflow-y-auto no-scrollbar px-3 py-3">
          {results === null ? (
            <>
              <div className="px-2 mb-3">
                <h2 className="font-display font-bold flex items-center gap-2" style={{ fontSize: 15, color: "#3D2A05", letterSpacing: "-0.015em" }}>
                  <span>📈</span><span>Trending duelists</span>
                </h2>
              </div>
              <div className="flex flex-col gap-2">
                {suggestions.map((u) => <SearchRow key={u.id} user={u} onView={() => onViewUser(u.id)} />)}
              </div>
            </>
          ) : results.length === 0 ? (
            <div className="text-center mt-12 px-6">
              <div style={{ fontSize: 42, marginBottom: 8 }}>🤔</div>
              <div className="font-display font-bold" style={{ fontSize: 16, color: "#3D2A05" }}>No fighters found</div>
              <div className="font-body" style={{ fontSize: 12, color: "rgba(58,42,5,0.55)", marginTop: 4 }}>Try another name</div>
            </div>
          ) : (
            <div className="flex flex-col gap-2">
              {results.map((u) => <SearchRow key={u.id} user={u} onView={() => onViewUser(u.id)} />)}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const ProfileHeroStat = ({ icon, value, label, theme = "teal", sparkleDelay = 0 }) => {
  const themes = {
    teal: {
      bg:         "linear-gradient(180deg, #FFFFFF 0%, #E8FAF3 100%)",
      borderGrad: "linear-gradient(135deg, #3DBA8C 0%, #1A8F6E 50%, #3DBA8C 100%)",
      drop:       "#0F6650",
      glow:       "rgba(61,186,140,0.55)",
      innerGlow:  "rgba(61,186,140,0.20)",
      number:     "#0F6650",
      label:      "#1A8F6E",
      sparkle:    "#3DBA8C",
    },
    gold: {
      bg:         "linear-gradient(180deg, #FFFFFF 0%, #FFF6D5 100%)",
      borderGrad: "linear-gradient(135deg, #FFD83A 0%, #FFA94D 50%, #FFD83A 100%)",
      drop:       "#B85020",
      glow:       "rgba(255,169,77,0.6)",
      innerGlow:  "rgba(255,216,58,0.22)",
      number:     "#B85020",
      label:      "#B85020",
      sparkle:    "#FFD83A",
    },
    fire: {
      bg:         "linear-gradient(180deg, #FFFFFF 0%, #FFECE5 100%)",
      borderGrad: "linear-gradient(135deg, #FF8A6A 0%, #E8444E 50%, #FF8A6A 100%)",
      drop:       "#A82530",
      glow:       "rgba(232,68,78,0.5)",
      innerGlow:  "rgba(255,138,106,0.22)",
      number:     "#A82530",
      label:      "#A82530",
      sparkle:    "#FF8A6A",
    },
  };
  const t = themes[theme];

  return (
    <div
      className="flex-1 rounded-2xl relative overflow-hidden tactile"
      style={{
        padding: "14px 6px 12px",
        background: t.bg,
        border: "2.5px solid transparent",
        backgroundImage: `${t.bg}, ${t.borderGrad}`,
        backgroundOrigin: "border-box",
        backgroundClip: "padding-box, border-box",
        boxShadow: `0 4px 0 ${t.drop}, 0 8px 18px ${t.glow}, inset 0 1px 0 rgba(255,255,255,0.7)`,
      }}
    >
      {/* Inner radial glow behind the number — gives the value a sense
          of warmth/aura without being a separate visual element. */}
      <div
        className="absolute pointer-events-none rounded-full"
        style={{
          top: "48%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: 78,
          height: 78,
          background: `radial-gradient(circle, ${t.innerGlow} 0%, transparent 70%)`,
        }}
      />
      {/* Corner sparkle — staggered per tile so the trio doesn't blink
          in sync. Reads as alive, not mechanical. */}
      <div
        className="absolute sparkle pointer-events-none"
        style={{
          top: 6, right: 8,
          fontSize: 11,
          color: t.sparkle,
          animationDelay: `${sparkleDelay}s`,
        }}
      >
        ✦
      </div>

      <div className="relative flex flex-col items-center">
        <div style={{ fontSize: 22, lineHeight: 1, marginBottom: 4 }}>{icon}</div>
        <div className="font-display font-bold" style={{
          fontSize: 26,
          color: t.number,
          letterSpacing: "-0.025em",
          lineHeight: 1,
          fontVariantNumeric: "tabular-nums",
          textShadow: "0 1.5px 0 rgba(255,255,255,0.75)",
          animation: "numberRise 700ms ease-out",
        }}>
          {typeof value === "number" ? value.toLocaleString() : value}
        </div>
        <div className="font-body font-bold uppercase" style={{
          fontSize: 9,
          color: t.label,
          letterSpacing: "0.14em",
          marginTop: 5,
          opacity: 0.95,
          whiteSpace: "nowrap",
        }}>
          {label}
        </div>
      </div>
    </div>
  );
};

