/* ============================================================
   DASH OBSTACLE — renders one obstacle by type. All are cute,
   small, and easy to clear. Types: bambooLow, bambooTall, stone,
   lanternPost.
   ============================================================ */
const DashObstacle = ({ type, w, h }) => {
  if (type === "platform") {
    // Floating bamboo beam — horizontal bar with leafy ends. Top surface
    // is landable. The rendered height is just the BEAM thickness, since
    // positioning logic places the beam at the right altitude.
    const beamH = 12;
    return (
      <svg width={w} height={beamH} viewBox={`0 0 ${w} ${beamH}`} style={{ display: "block", overflow: "visible" }}>
        {/* Beam — bamboo green with darker bottom for depth */}
        <rect x="6" y="2" width={w - 12} height="6"
              fill="#6FB870" stroke="#3D7A40" strokeWidth="0.7" rx="2.5" />
        <rect x="6" y="5" width={w - 12} height="3"
              fill="#5BA862" opacity="0.6" rx="1" />
        {/* Joint marks for bamboo segments */}
        {[0.25, 0.5, 0.75].map((p, i) => (
          <line key={i} x1={6 + (w - 12) * p} y1="2.5" x2={6 + (w - 12) * p} y2="7.5"
                stroke="#3D7A40" strokeWidth="0.6" />
        ))}
        {/* Subtle top highlight — suggests landability */}
        <rect x="8" y="1.5" width={w - 16} height="1.5"
              fill="rgba(255,255,255,0.45)" rx="0.5" />
        {/* Leafy ends */}
        <path d={`M 5 4 Q 0 0 -2 4 Q 1 3 5 6 Z`}
              fill="#6FB870" stroke="#3D7A40" strokeWidth="0.5" strokeLinejoin="round" />
        <path d={`M ${w - 5} 4 Q ${w + 2} 0 ${w + 4} 4 Q ${w + 1} 3 ${w - 5} 6 Z`}
              fill="#5BA862" stroke="#3D7A40" strokeWidth="0.5" strokeLinejoin="round" />
        {/* Tiny leaf on top, decorative */}
        <ellipse cx={w * 0.35} cy="0.5" rx="3" ry="1.2"
                 fill="#7FC676" stroke="#3D7A40" strokeWidth="0.4"
                 transform={`rotate(-20 ${w * 0.35} 0.5)`} />
      </svg>
    );
  }
  if (type === "bambooLow" || type === "bambooTall") {
    // Single bamboo stalk — short or tall. Two-leaf top.
    return (
      <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ display: "block", overflow: "visible" }}>
        <rect x={w/2 - 2} y="4" width="4" height={h - 4} fill="#5BA862" stroke="#3D7A40" strokeWidth="0.6" rx="1" />
        {/* Joint lines */}
        <line x1={w/2 - 3} y1={h * 0.32} x2={w/2 + 3} y2={h * 0.32} stroke="#3D7A40" strokeWidth="0.7" />
        <line x1={w/2 - 3} y1={h * 0.6}  x2={w/2 + 3} y2={h * 0.6}  stroke="#3D7A40" strokeWidth="0.7" />
        <line x1={w/2 - 3} y1={h * 0.85} x2={w/2 + 3} y2={h * 0.85} stroke="#3D7A40" strokeWidth="0.7" />
        {/* Top leaves */}
        <path d={`M ${w/2} 4 Q ${w/2 - 6} -2 ${w/2 - 3} 5 Z`}
              fill="#6FB870" stroke="#3D7A40" strokeWidth="0.5" strokeLinejoin="round" />
        <path d={`M ${w/2} 4 Q ${w/2 + 6} -2 ${w/2 + 3} 5 Z`}
              fill="#5BA862" stroke="#3D7A40" strokeWidth="0.5" strokeLinejoin="round" />
      </svg>
    );
  }
  if (type === "stone") {
    // Low boulder — wide and short, very easy hop
    return (
      <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ display: "block" }}>
        <ellipse cx={w/2} cy={h*0.65} rx={w/2 - 1} ry={h*0.5}
                 fill="#9A938A" stroke="#4A4540" strokeWidth="0.8" />
        <ellipse cx={w*0.4} cy={h*0.35} rx={w*0.25} ry={h*0.15}
                 fill="rgba(255,255,255,0.35)" />
      </svg>
    );
  }
  if (type === "lanternPost") {
    // Small lantern on a short post — medium-height obstacle
    return (
      <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`} style={{ display: "block", overflow: "visible" }}>
        {/* Post */}
        <rect x={w/2 - 1.5} y={h * 0.45} width="3" height={h * 0.55} fill="#7A5A3A" stroke="#3D2510" strokeWidth="0.5" />
        {/* Lantern */}
        <rect x="2" y={h * 0.18} width={w - 4} height={h * 0.28} fill="#C53030" stroke="#7A1717" strokeWidth="0.6" rx="1" />
        <rect x="4" y={h * 0.25} width={w - 8} height={h * 0.14} fill="#FFD83A" />
        {/* Lantern top */}
        <polygon points={`${w/2},2 1,${h*0.18} ${w-1},${h*0.18}`}
                 fill="#7A1717" stroke="#5A1010" strokeWidth="0.4" strokeLinejoin="round" />
      </svg>
    );
  }
  return null;
};

/* ============================================================
   MODE PICKER PILL — used in the START SESSION overlay. Tapping
   one of these pre-selects the session mode; START commits.
   ============================================================ */
const ModePickerPill = ({ mode, selected, icon, title, desc, onClick }) => (
  <button
    onClick={onClick}
    className="tactile flex items-center gap-3 w-full"
    style={{
      padding: "11px 14px",
      background: selected
        ? "linear-gradient(180deg, rgba(91,212,184,0.96) 0%, rgba(26,143,110,0.94) 100%)"
        : "rgba(255,255,255,0.06)",
      border: selected ? "1.5px solid #0A5A45" : "1.5px solid rgba(255,238,196,0.25)",
      borderRadius: 14,
      boxShadow: selected
        ? "0 3px 0 #0A5A45, inset 0 1px 0 rgba(255,255,255,0.3)"
        : "none",
      transition: "all 200ms",
      textAlign: "left",
    }}
  >
    <div style={{
      fontSize: 22,
      width: 36, height: 36,
      display: "flex", alignItems: "center", justifyContent: "center",
      background: selected ? "rgba(255,255,255,0.18)" : "rgba(255,255,255,0.04)",
      borderRadius: 10,
      border: selected ? "1px solid rgba(255,255,255,0.25)" : "1px solid rgba(255,238,196,0.12)",
    }}>{icon}</div>
    <div className="flex-1">
      <div className="font-display font-bold" style={{
        fontSize: 14,
        color: selected ? "#FFFEF6" : "#FFEEC4",
        letterSpacing: "0.02em",
        textShadow: selected ? "0 1px 0 rgba(0,0,0,0.25)" : "none",
      }}>{title}</div>
      <div className="font-body italic" style={{
        fontSize: 11,
        color: selected ? "rgba(255,254,246,0.8)" : "rgba(255,238,196,0.55)",
        marginTop: 1,
      }}>{desc}</div>
    </div>
    {selected && <span className="font-display font-bold" style={{
      fontSize: 16, color: "#FFFEF6",
      textShadow: "0 1px 0 rgba(0,0,0,0.25)",
    }}>✓</span>}
  </button>
);

const ShadowKataScreen = ({ onBack, onComplete, isReturning }) => {
  const SHADOW_PHRASES = getShadow();
  // Audio session state
  const [phraseIdx, setPhraseIdx] = useState(0);
  const [playIdx, setPlayIdx]     = useState(0);
  const [chosenSpeed, setChosenSpeed] = useState(0.9);
  const [audioPlaying, setAudioPlaying] = useState(false);
  const [sessionStarted, setSessionStarted] = useState(false);
  // Session mode: "kata" (tower-stack game), "dash" (puffling runner), "audio"
  // (no game, just shadowing). User picks before start AND can switch mid-
  // session via the mode switcher in the header.
  const [sessionMode, setSessionMode] = useState("kata");
  // Pre-selection toggled on the START overlay — committed to sessionMode
  // when the user actually presses START SESSION.
  const [selectedMode, setSelectedMode] = useState("kata");
  // Dash mode state — distance is the score, obstacles scroll in from the
  // right, puffling jumps to clear them. Hit one → distance freezes for
  // ~700ms (the stun), then resumes. No game over, just keep running.
  const [dashDistance, setDashDistance] = useState(0);
  const [dashStreak, setDashStreak] = useState(0);       // current no-hit streak
  const [dashBestStreak, setDashBestStreak] = useState(0); // longest streak this session
  const [dashCoins, setDashCoins] = useState(0);         // bonus coins grabbed off platforms
  const [collectedKata, setCollectedKata] = useState(() => new Set()); // kata coin keys kept
  const [coinPop, setCoinPop] = useState(false);         // brief "+1" feedback on grab
  const [coinPopAmt, setCoinPopAmt] = useState(1);       // how many grabbed in the last pop (kata can be >1)
  const [dashStunned, setDashStunned] = useState(false);
  const [dashPaused, setDashPaused] = useState(false);   // game paused via top-left button
  const [hasJumped, setHasJumped] = useState(false); // hint hides after first jump
  const [obstacles, setObstacles] = useState([]); // {id, x, type, h, w, kind}
  // Refs used by the rAF game loop (frame-rate-independent physics)
  const dashRAFRef        = useRef(null);
  const dashActiveRef     = useRef(false);
  const lastTimeRef       = useRef(0);
  const lastSpawnRef      = useRef(0);
  const pufflingYRef      = useRef(0);     // 0 = on ground; positive = airborne
  const pufflingVYRef     = useRef(0);     // vertical velocity (px/s)
  const isJumpingRef      = useRef(false);
  const isStunnedRef      = useRef(false);
  const stunUntilRef      = useRef(0);
  const distanceRef       = useRef(0);
  const streakRef         = useRef(0);     // current no-hit streak (resets on each hit)
  const bestStreakRef     = useRef(0);     // longest no-hit streak this session
  const dashCoinsRef      = useRef(0);     // bonus coins grabbed (mirrors dashCoins for the loop)
  const lastCoinSpawnRef  = useRef(0);     // timestamp of last platform coin spawn (rate cap)
  // Staircase cadence — a few normal obstacles, then a multi-platform staircase
  // with coins on top. Alternates 2-story / 3-story.
  const dashMacroIdxRef   = useRef(0);     // which macro step we're on (cycles)
  const normalsDoneRef    = useRef(0);     // normal obstacles spawned since last staircase
  const spawnDelayOverrideRef = useRef(null); // one-shot ms override for the NEXT spawn gap
  const dashEndPendingRef = useRef(false); // set when a collision after audioDone should end the session
  const collisionAtRef    = useRef(0);     // timestamp of last collision (for world-freeze + flash)
  const obstaclesRef      = useRef([]);    // mirrors obstacles state so the rAF loop sees fresh data
  const hasJumpedRef      = useRef(false); // false until first jump → gates scroll/spawn/score
  const dashPausedRef     = useRef(false); // game pause — freezes the rAF loop completely
  const nextObstacleIdRef = useRef(1);
  const pufflingDOMRef    = useRef(null);  // for direct transform updates
  const [redFlash, setRedFlash] = useState(false); // red overlay flash on impact
  const [showSummary, setShowSummary] = useState(false);

  // Tower for the CURRENT attempt. Resets on mid-session chops (after miss).
  const [stack, setStack] = useState([]);

  // Cumulative across the whole session, survives mid-session chops.
  // totalChopped = sum of every tower's height when it was chopped
  // bestTower = the tallest single attempt
  const [totalChopped, setTotalChopped] = useState(0);
  const [bestTower, setBestTower] = useState(0);

  // Chop animation state. `finalChopping` is now any chop animation in
  // progress (mid-session OR end-of-session). `audioDone` determines which
  // branch fires after the chop animation completes:
  //   audioDone=true  → big celebration text + transition to summary
  //   audioDone=false → reset tower and resume the game (audio keeps going)
  const [finalChopping, setFinalChopping] = useState(false);
  const [chopFlash, setChopFlash] = useState(false);
  const [showChopCount, setShowChopCount] = useState(false);
  const [audioDone, setAudioDone] = useState(false);

  // Dopamine layer
  const [score, setScore] = useState(0);
  const [combo, setCombo] = useState(0);
  const [totalPerfects, setTotalPerfects] = useState(0);
  const [pointsFloat, setPointsFloat] = useState(null);
  const [feedback, setFeedback] = useState(null);

  // Slide animation refs
  const slidingRef = useRef(null);
  const slidePos = useRef(0);
  const slideDir = useRef(1);
  const slideWidth = useRef(160);
  const slideActive = useRef(false);
  const rafRef = useRef(null);
  const lastTs = useRef(0);
  const canvasRef = useRef(null);
  const canvasWidth = useRef(360);

  // Refs mirroring state for audio callbacks
  const chosenSpeedRef = useRef(0.9);
  const sessionStartedRef = useRef(false);
  const stackRef = useRef([]);
  const collectedKataRef = useRef(new Set()); // mirrors collectedKata for the place handler
  const finalChoppingRef = useRef(false);
  const audioDoneRef = useRef(false);
  const sessionModeRef = useRef("kata");
  // Audio robustness refs: retain the live utterance (Chrome GCs local utterances
  // mid-phrase, which restarts them) and a generation token so a duplicate
  // onend/onerror can't double-advance and cancel the phrase that's playing.
  const utterRef = useRef(null);
  const audioTokenRef = useRef(0);
  useEffect(() => { chosenSpeedRef.current = chosenSpeed; }, [chosenSpeed]);
  useEffect(() => { sessionStartedRef.current = sessionStarted; }, [sessionStarted]);
  useEffect(() => { stackRef.current = stack; }, [stack]);
  useEffect(() => { finalChoppingRef.current = finalChopping; }, [finalChopping]);
  useEffect(() => { audioDoneRef.current = audioDone; }, [audioDone]);
  useEffect(() => { sessionModeRef.current = sessionMode; }, [sessionMode]);
  useEffect(() => { obstaclesRef.current = obstacles; }, [obstacles]);
  useEffect(() => { hasJumpedRef.current = hasJumped; }, [hasJumped]);
  useEffect(() => { dashPausedRef.current = dashPaused; }, [dashPaused]);

  const phrase = SHADOW_PHRASES[phraseIdx];

  // Measure canvas width
  useEffect(() => {
    const measure = () => {
      if (canvasRef.current) canvasWidth.current = canvasRef.current.offsetWidth;
    };
    measure();
    window.addEventListener("resize", measure);
    return () => window.removeEventListener("resize", measure);
  }, []);

  // Center-x of the k-th coin (of `count`) on a kata coin row — evenly spaced
  // across the playable width with a small margin on each side.
  const kataCoinX = (count, k) => {
    const W = canvasWidth.current;
    const margin = 34;
    return margin + ((k + 0.5) * (W - 2 * margin)) / count;
  };

  const spawnBoard = (width, startX = 0) => {
    // Defensive cap — never allow the board to fill the canvas (would
    // freeze the slider since maxX = canvasWidth - slideWidth would be 0).
    const safeWidth = Math.min(width, canvasWidth.current - 20);
    slideWidth.current = safeWidth;
    slidePos.current = Math.min(startX, Math.max(0, canvasWidth.current - safeWidth));
    if (slidingRef.current) {
      slidingRef.current.style.width = `${safeWidth}px`;
      slidingRef.current.style.transform = `translateX(${slidePos.current}px)`;
      slidingRef.current.style.opacity = "1";
    }
  };

  // Continuous 60fps slide loop
  const startSlideLoop = () => {
    cancelAnimationFrame(rafRef.current);
    lastTs.current = 0;
    slideActive.current = true;
    const loop = (ts) => {
      if (!slideActive.current) return;
      if (!lastTs.current) lastTs.current = ts;
      const dt = (ts - lastTs.current) / 1000;
      lastTs.current = ts;
      const maxX = Math.max(0, canvasWidth.current - slideWidth.current);
      slidePos.current += SLIDE_SPEED_PX_PER_SEC * slideDir.current * dt;
      if (slidePos.current >= maxX) { slidePos.current = maxX; slideDir.current = -1; }
      else if (slidePos.current <= 0) { slidePos.current = 0; slideDir.current = 1; }
      if (slidingRef.current) {
        slidingRef.current.style.transform = `translateX(${slidePos.current}px)`;
      }
      rafRef.current = requestAnimationFrame(loop);
    };
    rafRef.current = requestAnimationFrame(loop);
  };

  const stopSlideLoop = () => {
    slideActive.current = false;
    cancelAnimationFrame(rafRef.current);
  };

  useEffect(() => () => {
    stopSlideLoop();
    if (window.speechSynthesis) window.speechSynthesis.cancel();
  }, []);

  // Audio chain — plays each phrase 3 or 5 times (depending on seenBefore),
  // auto-advancing
  const playRound = (pIdx, plIdx) => {
    const ph = SHADOW_PHRASES[pIdx];
    if (!ph) return;
    const speed = plIdx === 0 ? 0.7 : chosenSpeedRef.current;
    setAudioPlaying(true);
    setPhraseIdx(pIdx);
    setPlayIdx(plIdx);

    if (window.speechSynthesis) {
      const synth = window.speechSynthesis;
      synth.cancel();
      const myToken = ++audioTokenRef.current;   // this round's generation id
      const utter = new SpeechSynthesisUtterance(ph.phrase);
      utter.lang = ph.speechLang || "es-MX";
      utter.rate = speed;
      utterRef.current = utter;                   // retain ref so Chrome can't GC + restart it mid-phrase
      let finished = false;
      const finish = () => {
        // onend AND onerror (and Chrome's occasional double onend) must only
        // advance ONCE — otherwise a second autoAdvance fires a new playRound
        // whose cancel() chops the phrase that's currently speaking.
        if (finished) return; finished = true;
        if (audioTokenRef.current !== myToken) return; // a newer round already took over
        setAudioPlaying(false);
        if (sessionStartedRef.current) setTimeout(() => autoAdvanceAudio(pIdx, plIdx), 800);
      };
      utter.onend = finish;
      utter.onerror = finish;
      // Small gap after cancel() avoids Chrome's cancel→speak race (which can drop
      // or instantly restart the new utterance). Skip if a newer round started.
      setTimeout(() => { if (audioTokenRef.current === myToken && window.speechSynthesis) window.speechSynthesis.speak(utter); }, 60);
    } else {
      setTimeout(() => {
        setAudioPlaying(false);
        if (sessionStartedRef.current) setTimeout(() => autoAdvanceAudio(pIdx, plIdx), 800);
      }, 2500);
    }
  };

  const autoAdvanceAudio = (fromPhrase, fromPlay) => {
    // Plays per phrase: 5 if first time seeing (locks it in), 3 if familiar.
    // Audio continues during mid-session chop animations too.
    const totalPlays = SHADOW_PHRASES[fromPhrase]?.seenBefore ? 3 : 5;
    const nextPlay = fromPlay + 1;
    if (nextPlay < totalPlays) {
      playRound(fromPhrase, nextPlay);
    } else {
      const nextPhrase = fromPhrase + 1;
      if (nextPhrase >= SHADOW_PHRASES.length) {
        // All phrases done. Audio session complete; user keeps playing the
        // final tower until they miss — that's when triggerChop will see
        // audioDoneRef and route to the celebration.
        setAudioDone(true);
        audioDoneRef.current = true;
        // Mode-specific endings after audio finishes:
        //   - kata:  keep stacking until a final miss (triggerChop)
        //   - dash:  keep running until a collision (tickDash routes to summary)
        //   - audio: nothing to wait for → route to summary after a beat
        if (sessionModeRef.current === "audio") {
          setTimeout(() => setShowSummary(true), 1400);
        }
        return;
      }
      setTimeout(() => playRound(nextPhrase, 0), 500);
    }
  };

  // ===== TRIGGER A CHOP ANIMATION =====
  // Fires on EITHER a miss (mid-session) OR audio completion (final). The
  // chop visual is the same in both cases. After the boards have flown,
  // branches based on audioDoneRef:
  //   - audioDone=true  → celebration + transition to summary
  //   - audioDone=false → reset tower, resume game (audio continues regardless)
  // Idempotent — second call while already chopping is a no-op.
  const triggerChop = () => {
    if (finalChoppingRef.current) return;
    // Snapshot audioDone AT THE START so the chop type is locked in. If
    // audio happens to finish during the 1.7s chop animation, the in-flight
    // chop is still treated as mid-session — the user gets the final tower.
    const isFinalChop = audioDoneRef.current;
    stopSlideLoop();
    setFinalChopping(true);
    finalChoppingRef.current = true;

    // Snapshot the tower height at chop time for cumulative stats
    const heightAtChop = stackRef.current.length;
    setTotalChopped((t) => t + heightAtChop);
    setBestTower((b) => Math.max(b, heightAtChop));

    // Chop visual sequence (~1.7s, same for mid and final)
    setTimeout(() => setChopFlash(true), 700);
    setTimeout(() => setChopFlash(false), 950);

    // After boards have flown, branch on the chop type we locked in
    setTimeout(() => {
      if (isFinalChop) {
        // FINAL: this miss came after audio completed → celebration + summary
        setShowChopCount(true);
        setTimeout(() => setShowSummary(true), 1800);
      } else {
        // MID-SESSION: reset the tower and resume. Audio still playing.
        // NOTE: collectedKata is intentionally NOT cleared here — a coin you've
        // already grabbed at a given spot stays gone for the rest of the
        // session, so you can't farm the same coin by replaying rounds.
        // Clear any lingering feedback (especially MISS — without this, it
        // would re-appear the moment finalChopping flips back to false and
        // sit on screen during the next round's first slide).
        setStack([]);
        stackRef.current = [];
        setCombo(0);
        setFeedback(null);
        setFinalChopping(false);
        finalChoppingRef.current = false;
        spawnBoard(Math.round(canvasWidth.current * 0.7), 0);
        slideDir.current = 1;
        startSlideLoop();
      }
    }, 1700);
  };

  // TAP — chop the sliding board. A miss triggers the chop animation but
  // does NOT end the session — the tower resets and the game restarts so
  // the user can keep listening + stacking through all the phrases.
  // ============= DASH MODE — auto-runner game =============
  // Bamboo Dash: puffling runs in place, world scrolls past, obstacles
  // approach from the right. Tap anywhere to jump. Hit an obstacle and
  // the puffling stumbles for ~700ms (distance counter freezes); recover
  // and keep running. No game-over. Goal: longest distance you can clock
  // through the audio session.
  const DASH = {
    SCROLL_SPEED:    175,   // px/sec — gentle, easy to react to
    GRAVITY:         3550,  // px/s² downward — slows upward velocity
    JUMP_VELOCITY:   800,   // px/s upward burst (peak ~90px, duration ~0.45s)
    PUFFLING_X:      72,    // fixed x position on screen
    GROUND_Y:        0,     // 0 = grounded; positive Y = altitude above ground
    SPAWN_BASE_MS:   2750,
    SPAWN_JITTER_MS: 600,
    STUN_MS:         550,   // visual stun duration after a hit
    PUFFLING_W:      58,    // was 48 — +20% bigger creature
    PUFFLING_H:      62,    // was 52
    PUFFLING_INSET_X: 14,   // collision hitbox trim per side (was 12)
    PLATFORM_THICKNESS: 8,  // how thick a platform beam is (visual + side hitbox)
    CANVAS_HEIGHT:   400,
  };

  // Obstacle types — all +20% bigger. `hitboxInsetX` shrinks the collision
  // box to match the rendered visual (bamboo stalks are skinny inside a
  // wider box, stone ellipse tapers at the edges, etc.) so hits register
  // only on genuine contact.
  const DASH_OBSTACLE_TYPES = [
    { type: "bambooLow",   w: 17, h: 38, weight: 3, kind: "obstacle", hitboxInsetX: 5 },
    { type: "stone",       w: 34, h: 22, weight: 2, kind: "obstacle", hitboxInsetX: 4 },
    { type: "bambooTall",  w: 17, h: 55, weight: 2, kind: "obstacle", hitboxInsetX: 5 },
    { type: "lanternPost", w: 22, h: 46, weight: 1, kind: "obstacle", hitboxInsetX: 4 },
    { type: "platform",    w: 94, h: 66, weight: 1, kind: "platform", hitboxInsetX: 7 },
  ];
  const spawnDashObstacle = (diff = 0) => {
    // Difficulty bias: as `diff` (0→1) climbs, the tougher/taller types gain
    // weight and the easy low bamboo fades, so the world grows more varied and
    // demanding the further you run.
    const weighted = DASH_OBSTACLE_TYPES.map((o) => {
      let w = o.weight;
      if (o.type === "bambooLow")   w = Math.max(1, w - diff * 1.5);
      if (o.type === "stone")       w += diff * 0.6;
      if (o.type === "bambooTall")  w += diff * 2.4;
      if (o.type === "lanternPost") w += diff * 2.0;
      if (o.type === "platform")    w += diff * 1.4;
      return { o, w };
    });
    const totalWeight = weighted.reduce((s, x) => s + x.w, 0);
    let r = Math.random() * totalWeight;
    let picked = weighted[0].o;
    for (const x of weighted) {
      if (r < x.w) { picked = x.o; break; }
      r -= x.w;
    }
    // Per-spawn size variation so obstacles aren't identical every time — kept
    // within jumpable bounds (jump peak is ~90px).
    const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
    const jit = (range) => Math.round((Math.random() * 2 - 1) * range);
    let h = picked.h, w = picked.w;
    if (picked.type === "bambooLow")   { h = clamp(picked.h + jit(5), 32, 44); w = picked.w + jit(2); }
    if (picked.type === "bambooTall")  { h = clamp(picked.h + jit(4), 50, 60); w = picked.w + jit(2); }
    if (picked.type === "stone")       { w = clamp(picked.w + jit(7), 26, 44); h = clamp(picked.h + jit(3), 18, 26); }
    if (picked.type === "lanternPost") { h = clamp(picked.h + jit(4), 40, 50); }
    return {
      id: nextObstacleIdRef.current++,
      x: 380,
      type: picked.type,
      w,
      h,
      kind: picked.kind,
      hitboxInsetX: picked.hitboxInsetX || 0,
    };
  };

  // Cadence of special staircases between normal obstacles: a 2-story climb
  // comes first, then (much later) a 3-story climb, then repeat. Top step = 2 coins.
  const DASH_MACRO = [
    { normals: 4, stories: 2 },
    { normals: 6, stories: 3 },
  ];
  // Build a staircase: `stories` platforms rising step by step so the puffling
  // hops up one at a time. Steps are LONG (room to stand and line up the next hop)
  // and widely spaced horizontally so the climb is fair at the normal scroll speed
  // — the world never slows for a staircase. Top step = 2 coins.
  const STAIR_STEP_W = 130;
  const STAIR_GAP_X  = 250;  // horizontal offset between consecutive steps (wide = time to jump each step at full speed)
  const STAIR_BASE_H = 56;   // height of the first (lowest) step
  const STAIR_RISE   = 52;   // height added per story
  const spawnStaircase = (stories) => {
    const group = [];
    for (let i = 0; i < stories; i++) {
      const isTop = i === stories - 1;
      group.push({
        id: nextObstacleIdRef.current++,
        x: 380 + i * STAIR_GAP_X,
        type: "platform",
        w: STAIR_STEP_W,
        h: STAIR_BASE_H + i * STAIR_RISE,
        kind: "platform",
        hitboxInsetX: 7,
        stair: true,
        coin: isTop,
        coinTaken: false,
        coinCount: isTop ? 2 : 0,
      });
    }
    return group;
  };

  const tickDash = (now) => {
    if (!dashActiveRef.current || sessionModeRef.current !== "dash") {
      dashRAFRef.current = null;
      return;
    }
    // Pause: keep the rAF chain alive but skip all updates. Reset the
    // timestamp baselines so when we unpause, dt is small and the spawn
    // timer doesn't fire immediately.
    if (dashPausedRef.current) {
      lastTimeRef.current = now;
      lastSpawnRef.current = now;
      dashRAFRef.current = requestAnimationFrame(tickDash);
      return;
    }
    if (!lastTimeRef.current) lastTimeRef.current = now;
    const dt = Math.min(0.05, (now - lastTimeRef.current) / 1000);
    lastTimeRef.current = now;

    // === Difficulty ramps with your NO-HIT STREAK: the longer you go without
    //     hitting anything, the faster the world scrolls and the more frequent
    //     the obstacles. Hitting something resets the streak (below), so the
    //     speed snaps back to baseline and climbs again. Caps so it stays fair. ===
    const dashDiff = Math.min(1, streakRef.current / 1000);
    // ONE constant pace driven only by the streak. Staircases do NOT change the
    // speed at all — they're made climbable purely by spacing the steps further
    // apart (see STAIR_GAP_X), so the player never feels a slow-down or speed-up.
    let dashSpeed = DASH.SCROLL_SPEED * (1 + dashDiff * 1.3);

    // === Compute effective ground level (real ground OR platform under puffling) ===
    // Walk all platforms; if puffling x-overlaps one AND is at or above its
    // top, that platform's top becomes the effective ground. This lets the
    // puffling land on platforms and run along them until they walk off the
    // edge (no x-overlap → ground returns to 0 → they fall).
    let groundLevel = 0;
    const pufflingLeft  = DASH.PUFFLING_X + DASH.PUFFLING_INSET_X;
    const pufflingRight = DASH.PUFFLING_X + DASH.PUFFLING_W - DASH.PUFFLING_INSET_X;
    for (const o of obstaclesRef.current) {
      if (o.kind !== "platform") continue;
      const oLeft  = o.x + (o.hitboxInsetX || 0);
      const oRight = o.x + o.w - (o.hitboxInsetX || 0);
      const xOverlap = oRight > pufflingLeft && oLeft < pufflingRight;
      if (xOverlap && pufflingYRef.current >= o.h - 12) {
        if (o.h > groundLevel) groundLevel = o.h;
      }
    }

    // === Physics: gravity is ALWAYS applied (so puffling falls off platforms
    //     when they scroll out from under them). Jump just adds upward velocity
    //     instantaneously; gravity erodes it each frame. Physics is paused
    //     during the brief post-collision world-freeze. ===
    const sinceCollisionPre = now - collisionAtRef.current;
    const physicsFrozen = collisionAtRef.current > 0 && sinceCollisionPre < 150;
    const wasGrounded = pufflingYRef.current <= groundLevel + 0.5 && pufflingVYRef.current === 0;
    if (!physicsFrozen && (!wasGrounded || isJumpingRef.current)) {
      pufflingYRef.current += pufflingVYRef.current * dt;
      pufflingVYRef.current -= DASH.GRAVITY * dt;
    }
    if (pufflingYRef.current <= groundLevel) {
      pufflingYRef.current = groundLevel;
      pufflingVYRef.current = 0;
      isJumpingRef.current = false;
    }

    // Sync puffling Y to DOM (direct transform — no React re-render).
    // During stun: bigger knockback + dramatic tilt so the hit is impossible
    // to miss. We use a fixed -22deg tilt (puffling falls backward) rather
    // than a fast wobble, which read as "dazed" but was too quick to register
    // in 400ms.
    if (pufflingDOMRef.current) {
      const knockback = isStunnedRef.current ? -22 : 0;
      const tilt      = isStunnedRef.current ? -22 : 0;
      pufflingDOMRef.current.style.transform =
        `translate(${knockback}px, ${-pufflingYRef.current}px) rotate(${tilt}deg)`;
      pufflingDOMRef.current.style.transition = isStunnedRef.current
        ? "transform 90ms ease-out"
        : "transform 200ms ease-out";
    }

    // === Stun timeout (just a visual flag — gameplay never paused) ===
    if (isStunnedRef.current && now >= stunUntilRef.current) {
      isStunnedRef.current = false;
      setDashStunned(false);
    }

    // === Spawn new obstacle — only after the user has tapped once. The
    //     pre-tap state is a static "tap to start" pose so the player can
    //     read the world before play begins. ===
    if (hasJumpedRef.current) {
      const base = DASH.SPAWN_BASE_MS - dashDiff * 1000;            // 2750 → 1750ms
      const jitter = DASH.SPAWN_JITTER_MS * (1 - dashDiff * 0.35);  // tighter when fast
      // A staircase leaves an extra-long gap after it (set via the override)
      // so the puffling has room to land from up high before the next obstacle.
      const interval = spawnDelayOverrideRef.current != null
        ? spawnDelayOverrideRef.current
        : base + (Math.random() - 0.5) * jitter;
      if (!lastSpawnRef.current) lastSpawnRef.current = now;
      if (now - lastSpawnRef.current >= interval) {
        lastSpawnRef.current = now;
        spawnDelayOverrideRef.current = null; // consume any one-shot override

        const macro = DASH_MACRO[dashMacroIdxRef.current % DASH_MACRO.length];
        if (normalsDoneRef.current >= macro.normals) {
          // === STAIRCASE TIME ===
          const group = spawnStaircase(macro.stories);
          setObstacles((prev) => [...prev, ...group]);
          normalsDoneRef.current = 0;
          dashMacroIdxRef.current += 1;
          // Extra room after the climb: footprint of the staircase + a generous
          // landing buffer, converted to a time gap at the current scroll speed.
          // The buffer scales steeply with climb height because a taller staircase
          // means a longer fall off the top step — during that descent the world
          // keeps scrolling, so the next ground object must start further out to
          // stay jumpable once the puffling lands.
          const footprintPx = (macro.stories - 1) * STAIR_GAP_X + STAIR_STEP_W;
          const landingBufferPx = 300 + macro.stories * 95; // taller climb = longer drop = more room
          spawnDelayOverrideRef.current = ((footprintPx + landingBufferPx) / dashSpeed) * 1000;
        } else {
          // === NORMAL OBSTACLE ===
          const newOb = spawnDashObstacle(dashDiff);
          setObstacles((prev) => [...prev, newOb]);
          normalsDoneRef.current += 1;
        }
      }
    } else {
      // Keep spawn timer aligned with "now" so the first obstacle doesn't
      // appear instantly the moment the user taps.
      lastSpawnRef.current = now;
    }

    // === Collision detection — pulled OUT of setObstacles so it runs
    //     deterministically once per frame, not whenever React decides to
    //     reconcile state. We read current obstacles directly. ===
    let collidedId = null;
    if (!isStunnedRef.current) {
      for (const o of obstaclesRef.current) {
        if (o.collided) continue;  // already hit — let it scroll past, no re-stun
        const inset = o.hitboxInsetX || 0;
        const obstacleLeft  = o.x + inset;
        const obstacleRight = o.x + o.w - inset;
        const xOverlap = obstacleRight > pufflingLeft && obstacleLeft < pufflingRight;
        if (!xOverlap) continue;

        if (o.kind === "platform") {
          // Platform side-collision uses the middle 50% of the puffling
          // body so a well-timed jump cleanly clears the side. Only fires
          // when puffling's hitbox intersects the beam from below or the
          // side (NOT when descending onto the top — that becomes a land
          // via the groundLevel calculation earlier in this frame).
          const platformBottom = o.h - DASH.PLATFORM_THICKNESS;
          const hitboxBottom = pufflingYRef.current + DASH.PUFFLING_H * 0.25;
          const hitboxTop    = pufflingYRef.current + DASH.PUFFLING_H * 0.75;
          const insideBeam =
            hitboxTop > platformBottom + 1 &&
            hitboxBottom < o.h - 1 &&
            pufflingYRef.current < o.h - 12;  // anything from here up = a land, not a hit
          if (insideBeam) { collidedId = o.id; break; }
        } else {
          // Once the obstacle's CENTER has passed the puffling's center,
          // we've "flown over" it — even if the trailing edge of its
          // hitbox is still x-overlapping our left side. This matches the
          // natural "I jumped over it" mental model: the moment it's
          // behind you, it can't hit you anymore.
          const obstacleCenterX = o.x + o.w / 2;
          const pufflingCenterX = DASH.PUFFLING_X + DASH.PUFFLING_W / 2;
          if (obstacleCenterX <= pufflingCenterX) continue;

          // Obstacle still in FRONT of the puffling: check clearance. The
          // -16 tolerance handles the brief frames-after-tap where the
          // puffling is rising fast but still at low altitude.
          const yClears = pufflingYRef.current >= o.h - 16;
          if (!yClears) {
            collidedId = o.id;
            break;
          }
        }
      }
    }

    // === Coin grab — collect a platform's coin(s) when you're up on/near its
    //     top and lined up over it. Staircase tops carry 2 coins. Added to the
    //     balance at session end. ===
    let collectedCoinId = null;
    let collectedCoinAmt = 0;
    for (const o of obstaclesRef.current) {
      if (o.kind !== "platform" || !o.coin || o.coinTaken) continue;
      const coinX = o.x + o.w / 2;
      const puffCenterX = DASH.PUFFLING_X + DASH.PUFFLING_W / 2;
      if (Math.abs(puffCenterX - coinX) < 32 && pufflingYRef.current >= o.h - 18) {
        collectedCoinId = o.id;
        collectedCoinAmt = o.coinCount || 1;
        break;
      }
    }
    if (collectedCoinId !== null) {
      // Mark in the ref immediately so it can't double-collect before the
      // state update lands next frame.
      for (const o of obstaclesRef.current) { if (o.id === collectedCoinId) o.coinTaken = true; }
      dashCoinsRef.current += collectedCoinAmt;
      setDashCoins(dashCoinsRef.current);
      setCoinPopAmt(collectedCoinAmt);
      setCoinPop(true);
      setTimeout(() => setCoinPop(false), 750);
    }

    // === World scroll — frozen for 150ms after impact so the hit lands
    //     with weight. By the time freeze ends, the colliding obstacle has
    //     been removed below, so no re-collision is possible. Also frozen
    //     before the very first tap (pre-tap idle pose). ===
    const sinceCollision = now - collisionAtRef.current;
    const isFrozen = collisionAtRef.current > 0 && sinceCollision < 150;
    const scrollDelta = (!hasJumpedRef.current || isFrozen) ? 0 : dashSpeed * dt;

    // === Move + cull obstacles. The one we just hit stays in the array
    //     (marked `collided`) so the user actually sees the contact during
    //     the stun. The collision check above skips collided obstacles to
    //     prevent re-stun. They scroll off-screen and get culled normally.
    setObstacles((prev) => {
      const updated = [];
      for (const o of prev) {
        const newX = o.x - scrollDelta;
        if (newX < -80) continue;                  // off-screen left
        if (o.id === collidedId) {
          updated.push({ ...o, x: newX, collided: true });
        } else if (o.id === collectedCoinId) {
          updated.push({ ...o, x: newX, coinTaken: true });
        } else {
          updated.push({ ...o, x: newX });
        }
      }
      return updated;
    });

    if (collidedId !== null) {
      // Save best streak if current beats it
      if (streakRef.current > bestStreakRef.current) {
        bestStreakRef.current = streakRef.current;
        setDashBestStreak(Math.floor(bestStreakRef.current));
      }
      streakRef.current = 0;
      setDashStreak(0);
      collisionAtRef.current = now;
      // Red flash overlay — 250ms fade out
      setRedFlash(true);
      setTimeout(() => setRedFlash(false), 260);

      if (audioDoneRef.current && !dashEndPendingRef.current) {
        // Bonus mode + hit → end session.
        dashEndPendingRef.current = true;
        isStunnedRef.current = true;
        stunUntilRef.current = now + 700;
        setDashStunned(true);
        setTimeout(() => {
          stopDashLoop();
          setShowSummary(true);
        }, 1100);
      } else {
        isStunnedRef.current = true;
        stunUntilRef.current = now + DASH.STUN_MS;
        setDashStunned(true);
      }
    }

    // === Distance + streak counters — both tick continuously AFTER the
    //     first tap. Pre-tap, both stay at 0 so the score doesn't sneak up
    //     before the player has begun playing. ===
    if (hasJumpedRef.current) {
      const distInc = dashSpeed * dt * 0.1;
      const prevDistFloor = Math.floor(distanceRef.current);
      distanceRef.current += distInc;
      if (Math.floor(distanceRef.current) !== prevDistFloor) {
        setDashDistance(Math.floor(distanceRef.current));
      }
      // Streak only increments when not stunned (gives a visible "freeze" beat
      // at the moment of impact). Pushed to state at ~15fps for display.
      if (!isStunnedRef.current) {
        const prevStreakFloor = Math.floor(streakRef.current);
        streakRef.current += distInc;
        if (Math.floor(streakRef.current) !== prevStreakFloor) {
          setDashStreak(Math.floor(streakRef.current));
        }
      }
    }

    dashRAFRef.current = requestAnimationFrame(tickDash);
  };

  const startDashLoop = () => {
    if (dashActiveRef.current) return;
    dashActiveRef.current = true;
    lastTimeRef.current = 0;
    lastSpawnRef.current = 0;
    dashRAFRef.current = requestAnimationFrame(tickDash);
  };

  const stopDashLoop = () => {
    dashActiveRef.current = false;
    if (dashRAFRef.current) {
      cancelAnimationFrame(dashRAFRef.current);
      dashRAFRef.current = null;
    }
  };

  const triggerJump = () => {
    if (isStunnedRef.current) return;
    if (isJumpingRef.current) return;
    isJumpingRef.current = true;
    pufflingVYRef.current = DASH.JUMP_VELOCITY;
    setHasJumped(true);
  };

  // Clean up dash loop on unmount
  useEffect(() => () => stopDashLoop(), []);

  const handleTap = (e) => {
    if (!sessionStarted || finalChopping) return;
    if (sessionMode === "dash") {
      // If paused, the tap just resumes (no jump). The pause button itself
      // stops propagation when clicked, so we only see canvas taps here.
      if (dashPaused) {
        setDashPaused(false);
        return;
      }
      triggerJump();
      return;
    }
    if (sessionMode !== "kata") return;
    const prev = stackRef.current.length > 0
      ? stackRef.current[stackRef.current.length - 1]
      // EMPTY STACK FALLBACK: use the slider's own current state. This
      // prevents the glitch where a centered tap on an empty stack would
      // make newBoard = full canvas width, which then froze the slider at
      // an edge (maxX = canvasWidth - canvasWidth = 0) and let the user
      // farm infinite PERFECTs.
      : { x: slidePos.current, width: slideWidth.current };
    const myX = slidePos.current;
    const myW = slideWidth.current;
    const overlapStart = Math.max(prev.x, myX);
    const overlapEnd = Math.min(prev.x + prev.width, myX + myW);
    const overlapWidth = Math.max(0, overlapEnd - overlapStart);

    if (overlapWidth <= 0) {
      // MISS — current attempt ends. Brief MISS! flash, then triggerChop:
      // mid-session it'll reset the tower for another go; if audio happened
      // to finish, it'll route to summary. Audio plays through regardless.
      setCombo(0);
      setFeedback({ type: "MISS", at: Date.now() });
      setTimeout(() => triggerChop(), 450);
      return;
    }

    // Place the board (any positive overlap counts, even slivers)
    const prevCenter = prev.x + prev.width / 2;
    const myCenter = myX + myW / 2;
    const offBy = Math.abs(prevCenter - myCenter);
    const isPerfect = offBy < 6;

    const newBoard = isPerfect
      ? { x: prev.x, width: prev.width }
      : { x: overlapStart, width: overlapWidth };

    const basePoints = Math.round(newBoard.width);
    const perfectBonus = isPerfect ? Math.round(newBoard.width * 0.5) : 0;
    const comboBonus = combo * 10;
    const earned = basePoints + perfectBonus + comboBonus;

    setScore((s) => s + earned);
    setPointsFloat({ value: earned, type: isPerfect ? "perfect" : "good", id: Date.now() });

    const newStack = [...stackRef.current, newBoard];
    setStack(newStack);
    stackRef.current = newStack;

    // === Coin grab — if this board lands on a coin row, keep every coin its
    //     width covers. Higher rows pack more (and more spread-out) coins, and
    //     boards get narrower as you climb, so you choose which to line up over. ===
    const newRow = newStack.length;
    const coinCfg = KATA_COIN_ROWS.find((r) => r.row === newRow);
    if (coinCfg) {
      const nextSet = new Set(collectedKataRef.current);
      let grabbed = 0;
      for (let k = 0; k < coinCfg.count; k++) {
        const key = `c${newRow}_${k}`;
        if (nextSet.has(key)) continue;
        const cx = kataCoinX(coinCfg.count, k);
        if (cx >= newBoard.x && cx <= newBoard.x + newBoard.width) {
          nextSet.add(key);
          grabbed++;
        }
      }
      if (grabbed > 0) {
        collectedKataRef.current = nextSet;
        setCollectedKata(nextSet);
        dashCoinsRef.current += grabbed;
        setDashCoins(dashCoinsRef.current);
        setCoinPopAmt(grabbed);
        setCoinPop(true);
        setTimeout(() => setCoinPop(false), 850);
      }
    }

    if (isPerfect) {
      setTotalPerfects((p) => p + 1);
      setCombo((c) => c + 1);
      setFeedback({ type: "PERFECT", at: Date.now() });
    } else {
      setCombo(0);
      setFeedback({ type: "GOOD", at: Date.now() });
    }
    setTimeout(() => setFeedback(null), 700);

    slideWidth.current = newBoard.width;
    slidePos.current = slideDir.current > 0
      ? 0
      : Math.max(0, canvasWidth.current - newBoard.width);
    if (slidingRef.current) {
      slidingRef.current.style.width = `${newBoard.width}px`;
      slidingRef.current.style.transform = `translateX(${slidePos.current}px)`;
    }
  };

  const startSession = () => {
    if (sessionStarted) return;
    // Commit the pre-selection (chosen via the mode picker on the START
    // overlay) to the live session mode.
    const mode = selectedMode;
    setSessionMode(mode);
    sessionModeRef.current = mode;
    setSessionStarted(true);
    sessionStartedRef.current = true;
    if (mode === "kata") {
      spawnBoard(Math.round(canvasWidth.current * 0.7), 0);
      startSlideLoop();
    } else if (mode === "dash") {
      startDashLoop();
    }
    playRound(0, 0);
  };

  // Mid-session mode switching. Audio loop continues uninterrupted; only
  // the game visualization changes. Switching INTO kata spawns a fresh
  // board + starts the slide loop. Switching INTO dash starts the runner.
  const switchMode = (newMode) => {
    if (newMode === sessionMode) return;
    const prevMode = sessionMode;
    setSessionMode(newMode);
    sessionModeRef.current = newMode;
    // Switching out of dash clears the pause state so the user doesn't
    // return to a mysteriously-paused game later.
    if (prevMode === "dash" && dashPaused) {
      setDashPaused(false);
    }
    // Stop whatever loop was running for the previous mode
    if (prevMode === "dash") stopDashLoop();
    if (prevMode === "kata") slideActive.current = false;
    // Start the loop for the new mode
    if (newMode === "kata" && prevMode !== "kata") {
      if (!finalChopping) {
        setTimeout(() => {
          spawnBoard(Math.round(canvasWidth.current * 0.7), 0);
          startSlideLoop();
        }, 50);
      }
    } else if (newMode === "dash") {
      setTimeout(() => startDashLoop(), 50);
    }
  };

  if (showSummary) {
    // 1 rep per phrase shadowed (not per audio play). Each phrase the Puffling
    // moves through = one rep, regardless of how many times the audio looped.
    const totalReps = SHADOW_PHRASES.length;
    return <ShadowSummary
      totalBoards={totalChopped}
      totalPerfects={totalPerfects}
      bestTower={bestTower}
      score={score}
      sessionMode={sessionMode}
      dashDistance={dashDistance}
      dashBestStreak={dashBestStreak}
      dashCoins={dashCoins}
      phrasesCount={SHADOW_PHRASES.length}
      totalReps={totalReps}
      onComplete={onComplete}
    />;
  }

  const cameraOffset = Math.max(0, (stack.length - VISIBLE_TOWER_BOARDS) * BOARD_HEIGHT);
  const towerBase = TOWER_BASE_BOTTOM - cameraOffset;

  return (
    <div className="relative w-full h-full overflow-hidden" style={{
      background: "linear-gradient(180deg, #2D1F12 0%, #3D2A18 45%, #4A3220 100%)",
    }}>
      {/* Dojo floor (kata/audio) — wood-grain background. NOT in dash
          (dash has its own sand path). */}
      {sessionMode !== "dash" && (
        <div className="absolute inset-x-0 bottom-0 pointer-events-none" style={{
          height: "30%",
          background: "linear-gradient(180deg, rgba(120,75,30,0) 0%, rgba(80,50,20,0.55) 100%), repeating-linear-gradient(0deg, rgba(0,0,0,0.08) 0px, rgba(0,0,0,0.08) 1px, transparent 1px, transparent 18px)",
        }} />
      )}
      {/* Dash mode background — cozy dawn scene with parallax layers.
          Always visible in dash mode (no scripted reveals here; this is
          the world the puffling runs through). */}
      {sessionMode === "dash" && (
        <>
          {/* Sun — warm halo in upper right */}
          <div className="absolute pointer-events-none" style={{
            top: 22, right: 32, width: 52, height: 52, zIndex: 1,
            background: "radial-gradient(circle, #FFE8C8 0%, #FFC890 45%, rgba(255,200,140,0) 78%)",
            borderRadius: "50%",
            animation: "preSessionGlow 5s ease-in-out infinite",
          }} />
          {/* Far mountains — softest layer */}
          <svg width="100%" height="70" viewBox="0 0 400 70" preserveAspectRatio="none" style={{
            position: "absolute", top: 60, left: 0, opacity: 0.4, zIndex: 1, pointerEvents: "none",
          }}>
            <path d="M 0 70 L 40 30 L 90 50 L 140 18 L 200 42 L 250 24 L 300 52 L 350 32 L 400 54 L 400 70 Z"
                  fill="#9B8FA8" />
          </svg>
          {/* Mid mountains */}
          <svg width="100%" height="90" viewBox="0 0 400 90" preserveAspectRatio="none" style={{
            position: "absolute", top: 95, left: 0, opacity: 0.55, zIndex: 1, pointerEvents: "none",
          }}>
            <path d="M 0 90 L 70 42 L 135 68 L 215 32 L 280 62 L 340 44 L 400 70 L 400 90 Z"
                  fill="#7E97A5" />
          </svg>
          {/* Pagoda silhouettes — cozy distant skyline */}
          <svg width="60" height="56" viewBox="0 0 60 56" style={{
            position: "absolute", top: 110, left: 80, zIndex: 2, pointerEvents: "none",
            opacity: 0.45,
          }}>
            {/* 3-tier pagoda silhouette */}
            <polygon points="30,2 18,12 42,12" fill="#5A4255" />
            <rect x="22" y="12" width="16" height="8" fill="#5A4255" />
            <polygon points="30,16 12,28 48,28" fill="#5A4255" />
            <rect x="22" y="28" width="16" height="8" fill="#5A4255" />
            <polygon points="30,32 8,44 52,44" fill="#5A4255" />
            <rect x="24" y="44" width="12" height="12" fill="#5A4255" />
          </svg>
          <svg width="40" height="36" viewBox="0 0 40 36" style={{
            position: "absolute", top: 130, left: 260, zIndex: 2, pointerEvents: "none",
            opacity: 0.4,
          }}>
            {/* 2-tier smaller pagoda */}
            <polygon points="20,2 12,8 28,8" fill="#5A4255" />
            <rect x="15" y="8" width="10" height="6" fill="#5A4255" />
            <polygon points="20,12 6,20 34,20" fill="#5A4255" />
            <rect x="16" y="20" width="8" height="16" fill="#5A4255" />
          </svg>
          {/* Distant bamboo grove hint */}
          <div className="absolute pointer-events-none" style={{
            top: 145, left: 0, right: 0, height: 60, zIndex: 2,
            background: "linear-gradient(180deg, rgba(110,140,80,0) 0%, rgba(110,140,80,0.3) 100%)",
          }} />
          {/* Ground / running path — bottom strip, warm sand */}
          <div className="absolute inset-x-0 bottom-0 pointer-events-none" style={{
            height: 50, zIndex: 3,
            background: "linear-gradient(180deg, #D8B888 0%, #C29870 40%, #A87C58 100%)",
            borderTop: "2px solid #8B5E3A",
          }} />
          {/* Grass tufts on the path for cozy detail */}
          {[40, 130, 200, 290].map((x, i) => (
            <svg key={`grass-${i}`} width="14" height="6" viewBox="0 0 14 6" style={{
              position: "absolute", bottom: 46, left: x, zIndex: 4, opacity: 0.7,
            }}>
              <path d="M 2 6 Q 1 0 3 1 M 5 6 Q 5 -1 7 0 M 8 6 Q 8 0 10 1 M 11 6 Q 11 -1 13 0"
                    fill="none" stroke="#6B8856" strokeWidth="1" strokeLinecap="round" />
            </svg>
          ))}
          {/* Ambient falling cherry petals — continuous cozy rain */}
          {sessionStarted && [0, 1, 2, 3, 4, 5, 6, 7].map((i) => (
            <div key={`petal-${i}`} className="absolute pointer-events-none" style={{
              left: `${(i * 13 + 4) % 95}%`,
              top: -14, zIndex: 12,
              animation: `petalFall ${9 + (i % 3) * 1.4}s linear infinite ${i * 1.1}s`,
            }}>
              <svg width="10" height="10" viewBox="0 0 10 10">
                <ellipse cx="5" cy="5" rx="2" ry="4"
                         fill={i % 2 === 0 ? "#FFCAD4" : "#FFB6C1"}
                         stroke="#E89DA8" strokeWidth="0.3"
                         transform={`rotate(${i * 35} 5 5)`} />
              </svg>
            </div>
          ))}
        </>
      )}

      {/* Header — back button + mid-session mode switcher + phrase counter.
          The three mode pills are tappable AFTER the session starts;
          before that, the START overlay's larger picker handles selection. */}
      <div className="relative flex items-center justify-between px-3 pt-3 z-10">
        <button onClick={onBack} className="rounded-full flex items-center justify-center tactile" style={{
          width: 36, height: 36, background: "rgba(255,255,255,0.12)", color: "#FFEEC4",
          fontSize: 18, fontWeight: 700, border: "1.5px solid rgba(255,238,196,0.25)",
        }}>←</button>
        <div className="flex flex-col items-center gap-1">
          {/* Mode switcher — three pills, current mode highlighted */}
          <div className="flex items-center gap-1">
            {[
              { mode: "kata",  icon: "🥋" },
              { mode: "dash",  icon: "🎋" },
              { mode: "audio", icon: "🎧" },
            ].map((m) => {
              const active = sessionMode === m.mode;
              return (
                <button
                  key={m.mode}
                  onClick={() => sessionStarted && switchMode(m.mode)}
                  className="tactile flex items-center justify-center"
                  style={{
                    width: 32, height: 26,
                    background: active
                      ? "linear-gradient(180deg, rgba(91,212,184,0.95) 0%, rgba(26,143,110,0.92) 100%)"
                      : "rgba(255,255,255,0.06)",
                    border: active ? "1.5px solid #0A5A45" : "1.5px solid rgba(255,238,196,0.18)",
                    borderRadius: 8,
                    fontSize: 14,
                    boxShadow: active ? "0 2px 0 #0A5A45, inset 0 1px 0 rgba(255,255,255,0.3)" : "none",
                    opacity: sessionStarted ? 1 : 0.5,
                    cursor: sessionStarted ? "pointer" : "default",
                    transition: "background 200ms, border 200ms, box-shadow 200ms, opacity 200ms",
                  }}
                >
                  {m.icon}
                </button>
              );
            })}
          </div>
          {/* Phrase counter (or FINAL TOWER alert in kata when audio's done) */}
          <div className="font-display font-bold" style={{
            fontSize: 12,
            color: (audioDone && sessionMode === "kata") ? "#FFD83A" : "rgba(255,238,196,0.85)",
            letterSpacing: "0.04em",
            textShadow: (audioDone && sessionMode === "kata") ? "0 0 12px rgba(255,216,58,0.6)" : "none",
            transition: "color 400ms, text-shadow 400ms",
          }}>
            {(audioDone && sessionMode === "kata")
              ? "🥋 FINAL TOWER"
              : `Phrase ${phraseIdx + 1} of ${SHADOW_PHRASES.length}`}
          </div>
        </div>
        <div style={{ width: 36 }} />
      </div>

      {/* Phrase banner. Pre-session: an inviting "ready to train" card. In
          session: the phrase + translation + a progress bar showing how
          many reps remain for the current phrase (5 for new phrases the
          user is locking in, 3 for familiar ones). */}
      <div className="relative px-4 pt-3 pb-3 z-10">
        {(() => {
          const currentPhraseData = SHADOW_PHRASES[phraseIdx];
          const totalPlaysForCurrent = currentPhraseData?.seenBefore ? 3 : 5;
          // (playIdx + 1) / total — bar is "full" during the last play
          const progressPct = sessionStarted
            ? Math.min(100, ((playIdx + 1) / totalPlaysForCurrent) * 100)
            : 0;
          return sessionStarted ? (
            <div className="rounded-2xl text-center" style={{
              padding: "12px 16px 10px",
              // Cream gradient — clearly warm/cream throughout (no near-white
              // at the top), still distinct from the gold tap targets. Teal
              // outline + shadow match the score pill.
              background: "linear-gradient(180deg, #FBF1DC 0%, #F2DEA8 100%)",
              border: "1.5px solid #0A5A45",
              boxShadow: "0 3px 0 #0A5A45, inset 0 1px 0 rgba(255,255,255,0.6)",
            }}>
              <div className="font-display font-bold" style={{
                fontSize: 24, color: "#3D2A05", letterSpacing: "-0.01em", lineHeight: 1.1,
              }}>{currentPhraseData?.phrase}</div>
              {/* Pronunciation aid — English sound-it-out respelling (say), the
                  thing a beginner can actually read aloud. Falls back to the RR
                  (phon) in /.../ only if no respelling exists for this phrase.
                  RR is intentionally NOT shown when a respelling is present. */}
              {(currentPhraseData?.say || currentPhraseData?.phon) && (
                <div className="font-body" style={{
                  fontSize: 15,
                  color: "#1A8F6E",
                  fontWeight: 700,
                  letterSpacing: "0.01em",
                  marginTop: 4,
                }}>{currentPhraseData?.say || `/${currentPhraseData.phon}/`}</div>
              )}
              <div className="font-body italic mt-1" style={{
                fontSize: 13, color: "rgba(58,42,5,0.7)",
              }}>{currentPhraseData?.translation}</div>
              {/* Progress bar — teal fill to match the new banner theme */}
              <div className="flex items-center gap-2 mt-2.5">
                <div style={{
                  flex: 1, height: 6,
                  background: "rgba(10,90,69,0.16)",
                  borderRadius: 999,
                  overflow: "hidden",
                  boxShadow: "inset 0 1px 1px rgba(10,90,69,0.2)",
                }}>
                  <div style={{
                    width: `${progressPct}%`, height: "100%",
                    background: "linear-gradient(90deg, #0A5A45 0%, #1A8F6E 50%, #5BD4B8 100%)",
                    borderRadius: 999,
                    transition: "width 450ms cubic-bezier(0.34, 1.56, 0.64, 1)",
                    boxShadow: "inset 0 1px 0 rgba(255,255,255,0.4)",
                  }} />
                </div>
                <span className="font-display font-bold" style={{
                  fontSize: 10,
                  color: "#0A5A45",
                  letterSpacing: "0.06em",
                  fontVariantNumeric: "tabular-nums",
                  minWidth: 26,
                  textAlign: "right",
                }}>
                  {playIdx + 1}/{totalPlaysForCurrent}
                </span>
              </div>
            </div>
          ) : (
            // PRE-SESSION — pretty placeholder. Soft teal-blue gradient with
            // a martial-arts vibe, gentle glow on the 🥋 icon, inviting copy.
            <div className="rounded-2xl text-center relative overflow-hidden" style={{
              padding: "14px 16px 13px",
              background: "linear-gradient(180deg, rgba(75,188,240,0.16) 0%, rgba(26,143,110,0.20) 100%)",
              border: "1.5px solid rgba(255,238,196,0.28)",
              boxShadow: "inset 0 1px 0 rgba(255,255,255,0.12), 0 2px 12px rgba(75,188,240,0.08)",
            }}>
              {/* Decorative ambient glow */}
              <div className="absolute pointer-events-none" style={{
                top: -20, left: "calc(50% - 40px)", width: 80, height: 80,
                background: "radial-gradient(circle, rgba(255,216,58,0.25) 0%, transparent 70%)",
                animation: "preSessionGlow 2.4s ease-in-out infinite",
              }} />
              <div className="relative" style={{
                fontSize: 30,
                filter: "drop-shadow(0 2px 6px rgba(255,216,58,0.35))",
                animation: "preSessionGlow 2.4s ease-in-out infinite",
              }}>🥋</div>
              <div className="font-display font-bold mt-1.5 relative mx-auto" style={{
                fontSize: 15,
                color: "#FFEEC4",
                lineHeight: 1.3,
                maxWidth: 260,
                textShadow: "0 1px 0 rgba(0,0,0,0.3)",
              }}>
                Hear each phrase, then echo it out loud to match the rhythm.
              </div>
            </div>
          );
        })()}
      </div>

      {/* GAME CANVAS */}
      <div
        ref={canvasRef}
        onClick={handleTap}
        className="relative mx-3 mb-3 rounded-2xl overflow-hidden"
        style={{
          height: 400,
          background: sessionMode === "dash"
            // Cozy dawn sky — warm pink/peach top fading to mint/sand
            ? "linear-gradient(180deg, #FBD9C8 0%, #F2BFBA 18%, #D4B5C5 35%, #B7C5C5 55%, #D4C5A0 80%, #E5CFA4 100%)"
            : "radial-gradient(ellipse at center top, rgba(255,232,154,0.08) 0%, transparent 70%), linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.08) 100%)",
          border: "2px solid rgba(255,238,196,0.18)",
          boxShadow: "inset 0 2px 8px rgba(0,0,0,0.3)",
          cursor: sessionStarted && !finalChopping && (sessionMode === "kata" || sessionMode === "dash") ? "pointer" : "default",
        }}
      >
        {/* SCORE pill — only in kata mode (zen has no score, audio has no
            game). Teal so it doesn't compete with the gold tap targets. */}
        <div className="absolute" style={{
          top: 10, right: 10, zIndex: 8, display: "flex", alignItems: "center", gap: 5,
          padding: "5px 11px 5px 9px",
          background: "linear-gradient(180deg, rgba(91,212,184,0.96) 0%, rgba(26,143,110,0.94) 100%)",
          borderRadius: 999, border: "1.5px solid #0A5A45",
          boxShadow: "0 3px 0 #0A5A45, inset 0 1px 0 rgba(255,255,255,0.35)",
          opacity: (finalChopping || sessionMode !== "kata" || !sessionStarted) ? 0 : 1,
          pointerEvents: (sessionMode === "kata" && sessionStarted) ? "auto" : "none",
          transition: "opacity 400ms",
        }}>
          <span style={{ fontSize: 13 }}>⭐</span>
          <span className="font-display font-bold" style={{
            fontSize: 15, color: "#FFFEF6", fontVariantNumeric: "tabular-nums",
            letterSpacing: "-0.01em", minWidth: 32, textAlign: "right",
            textShadow: "0 1px 0 rgba(0,0,0,0.25)",
          }}>{score.toLocaleString()}</span>
        </div>

        {/* +N popup */}
        {pointsFloat && !finalChopping && (
          <div
            key={pointsFloat.id}
            className="absolute pointer-events-none font-display font-bold"
            style={{
              top: 42, right: 18,
              fontSize: pointsFloat.type === "perfect" ? 22 : 18,
              color: pointsFloat.type === "perfect" ? "#FFD83A" : "#FFEEC4",
              textShadow: pointsFloat.type === "perfect"
                ? "0 2px 0 rgba(123,60,5,0.85), 0 0 16px rgba(255,216,58,0.6)"
                : "0 2px 0 rgba(0,0,0,0.45)",
              WebkitTextStroke: pointsFloat.type === "perfect" ? "1px #7B3C05" : "0.5px rgba(0,0,0,0.4)",
              animation: "pointsRise 850ms cubic-bezier(0.22, 1, 0.36, 1) forwards",
              zIndex: 9, letterSpacing: "-0.01em",
            }}
          >+{pointsFloat.value}</div>
        )}

        {/* Puffling beside the tower — facing the user. On each tap, the
            body does a small lean (pufflingChop) AND a small "flipper" arm
            element overlays a karate-chop swing (armChop). The chop arm
            extends from the Puffling's right shoulder toward the tower.
            Hidden in audio-only mode; the listening view below shows a
            larger calm Puffling in its place. */}
        {sessionMode === "kata" && sessionStarted && (
        <div className="absolute" style={{
          left: 8, bottom: 14, zIndex: 5,
          width: 60, height: 60,
          animation: finalChopping
            ? "pufflingFinalChop 1200ms cubic-bezier(0.34, 1.56, 0.64, 1) forwards"
            : (feedback?.type === "PERFECT" || feedback?.type === "GOOD")
              ? "pufflingChop 360ms ease-out"
              : "none",
        }}>
          <BattlePuffling state="fighting" facing="right" size={60} belt="orange" />

          {/* Karate-chop arm — body-colored SVG flipper, briefly appears and
              swings on each successful tap. Pivots from the shoulder (left
              edge). Same cyan as the Puffling body so it reads as the
              creature's own arm, not a separate cream object. */}
          <div className="absolute pointer-events-none" style={{
            left: 42, top: 26,
            width: 22, height: 8,
            transformOrigin: "0% 50%",
            opacity: 0,
            zIndex: 6,
            filter: "drop-shadow(0 1px 1px rgba(0,0,0,0.25))",
            animation: (feedback?.type === "PERFECT" || feedback?.type === "GOOD")
              ? "armChop 360ms ease-out"
              : "none",
          }}>
            <svg width="22" height="8" viewBox="0 0 22 8">
              {/* Tapered flipper shape — wider at the shoulder, gently
                  rounded at the tip. Body color #7FC8E0 fill, wing-edge
                  #3A7A9A outline matches the Puffling's other accents. */}
              <path
                d="M 1 4 Q 3 1.2 11 1.5 Q 20 2 21 4 Q 20 6 11 6.5 Q 3 6.8 1 4 Z"
                fill="#7FC8E0"
                stroke="#3A7A9A"
                strokeWidth="1"
                strokeLinejoin="round"
              />
              {/* Subtle top-edge highlight — gives the flipper a little
                  dimension at this tiny size */}
              <path
                d="M 4 2.7 Q 11 1.8 18 2.8"
                fill="none"
                stroke="rgba(255,255,255,0.5)"
                strokeWidth="0.8"
                strokeLinecap="round"
              />
            </svg>
          </div>
        </div>
        )}

        {/* DASH MODE — auto-runner game. Puffling runs in place on the
            path, obstacles scroll in from the right, tap anywhere to
            jump. Hit one → stunned briefly (distance freezes) but no
            game over — just keep running. */}
        {sessionMode === "dash" && (
          <>
            {/* Pause button — top-left, gold + glowing. Appears only after
                the user dismisses the TAP TO START overlay (first jump),
                so the pre-game state stays clean. Stops event propagation
                so the canvas tap-to-jump doesn't also fire. */}
            {sessionStarted && hasJumped && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  setDashPaused((p) => !p);
                }}
                className="tactile absolute"
                style={{
                  top: 10, left: 10, zIndex: 16,
                  width: 38, height: 38,
                  padding: 0,
                  background: dashPaused
                    ? "linear-gradient(180deg, #B5E8C8 0%, #6FCC8F 60%, #3D9656 100%)"
                    : "linear-gradient(180deg, #FFE066 0%, #FBBB05 60%, #E89600 100%)",
                  border: dashPaused ? "1.5px solid #1F6A36" : "1.5px solid #8A5A00",
                  borderRadius: 12,
                  boxShadow: dashPaused
                    ? "0 3px 0 #1F6A36, inset 0 1px 0 rgba(255,255,255,0.45), 0 0 14px rgba(95,200,135,0.55)"
                    : "0 3px 0 #8A5A00, inset 0 1px 0 rgba(255,255,255,0.45), 0 0 14px rgba(251,187,5,0.55)",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 14,
                  color: "#3D2510",
                  animation: "pauseButtonPulse 2.4s ease-in-out infinite",
                  transition: "background 200ms, border 200ms, box-shadow 200ms",
                }}
              >
                {dashPaused ? (
                  // PLAY icon (resume)
                  <svg width="13" height="14" viewBox="0 0 13 14" style={{ marginLeft: 2 }}>
                    <polygon points="1.5,1 1.5,13 12,7" fill="#1F3F26"
                             stroke="#1F3F26" strokeWidth="0.8" strokeLinejoin="round" />
                  </svg>
                ) : (
                  // PAUSE icon (two bars)
                  <svg width="12" height="14" viewBox="0 0 12 14">
                    <rect x="1.5" y="1" width="3.2" height="12" fill="#3D2510" rx="0.8" />
                    <rect x="7.3" y="1" width="3.2" height="12" fill="#3D2510" rx="0.8" />
                  </svg>
                )}
              </button>
            )}

            {/* PAUSED overlay — centered card, dims the world behind. The
                canvas onClick handles tap-to-resume (no jump fires). */}
            {sessionStarted && dashPaused && (
              <div className="absolute inset-0 flex items-center justify-center" style={{
                background: "rgba(0,0,0,0.42)",
                backdropFilter: "blur(2.5px)",
                WebkitBackdropFilter: "blur(2.5px)",
                zIndex: 15,
              }}>
                <div className="text-center" style={{
                  padding: "16px 28px 18px",
                  background: "linear-gradient(180deg, rgba(181,232,200,0.97) 0%, rgba(111,204,143,0.94) 100%)",
                  borderRadius: 20,
                  border: "2.5px solid #1F6A36",
                  boxShadow: "0 6px 0 #1F6A36, 0 0 28px rgba(95,200,135,0.5), inset 0 1px 0 rgba(255,255,255,0.5)",
                }}>
                  <div style={{ fontSize: 22, marginBottom: 3, lineHeight: 1 }}>
                    <svg width="18" height="20" viewBox="0 0 18 20" style={{ display: "inline-block" }}>
                      <rect x="2.5" y="2" width="4.5" height="16" fill="#1F3F26" rx="1" />
                      <rect x="11" y="2" width="4.5" height="16" fill="#1F3F26" rx="1" />
                    </svg>
                  </div>
                  <div className="font-display font-bold uppercase" style={{
                    fontSize: 18, color: "#1F3F26", letterSpacing: "0.12em",
                    textShadow: "0 1px 0 rgba(255,255,255,0.4)",
                    lineHeight: 1.1, marginTop: 2,
                  }}>Paused</div>
                  <div className="font-body font-bold uppercase" style={{
                    fontSize: 10, color: "rgba(31,63,38,0.75)",
                    letterSpacing: "0.18em", marginTop: 5, lineHeight: 1,
                  }}>tap to resume</div>
                </div>
              </div>
            )}

            {/* Red flash overlay — fires on collision for 250ms. High zIndex
                so it sits above everything but the score pill. Unmistakable
                "you hit something" feedback. */}
            {redFlash && (
              <div className="absolute inset-0 pointer-events-none" style={{
                background: "rgba(232,68,78,0.42)",
                mixBlendMode: "multiply",
                zIndex: 14,
                animation: "redFlashFade 260ms ease-out forwards",
              }} />
            )}

            {/* Live readout — top-right. Big number is current streak
                (resets on each hit); small number below is total session
                distance (cumulative through hits). Visually swaps to a red
                stunned style on collision. */}
            {sessionStarted && (
              <div className="absolute flex flex-col items-end" style={{
                top: 10, right: 10, zIndex: 13, gap: 2,
                padding: "5px 11px 6px 11px",
                background: dashStunned
                  ? "linear-gradient(180deg, rgba(255,180,180,0.96) 0%, rgba(232,68,78,0.92) 100%)"
                  : "linear-gradient(180deg, rgba(91,212,184,0.96) 0%, rgba(26,143,110,0.94) 100%)",
                borderRadius: 14,
                border: dashStunned ? "1.5px solid #A82530" : "1.5px solid #0A5A45",
                boxShadow: dashStunned
                  ? "0 3px 0 #A82530, inset 0 1px 0 rgba(255,255,255,0.35)"
                  : "0 3px 0 #0A5A45, inset 0 1px 0 rgba(255,255,255,0.35)",
                transition: "background 200ms, border 200ms, box-shadow 200ms",
                minWidth: 84,
              }}>
                <div className="flex items-center" style={{ gap: 4 }}>
                  <span style={{ fontSize: 13 }}>{dashStunned ? "💫" : "🔥"}</span>
                  <span className="font-display font-bold" style={{
                    fontSize: 16, color: "#FFFEF6", fontVariantNumeric: "tabular-nums",
                    letterSpacing: "-0.01em",
                    textShadow: "0 1px 0 rgba(0,0,0,0.3)",
                    lineHeight: 1,
                  }}>{dashStreak}m</span>
                </div>
                <div className="font-body font-bold uppercase" style={{
                  fontSize: 8, color: "rgba(255,254,246,0.78)",
                  letterSpacing: "0.1em", fontVariantNumeric: "tabular-nums",
                  lineHeight: 1,
                }}>
                  total {dashDistance}m
                </div>
              </div>
            )}

            {/* BONUS banner — appears when audio is done but session continues.
                Reminds the user the next hit ends the run. Outer div handles
                centering; inner div handles the pulsing scale (the two have
                to be separate so the animation's transform doesn't clobber
                the centering translateX). */}
            {sessionStarted && audioDone && !dashEndPendingRef.current && (
              <div className="absolute pointer-events-none" style={{
                top: 64, left: "50%", transform: "translateX(-50%)", zIndex: 13,
              }}>
                <div className="font-display font-bold uppercase" style={{
                  padding: "6px 14px",
                  background: "linear-gradient(180deg, rgba(251,187,5,0.96) 0%, rgba(232,150,0,0.94) 100%)",
                  color: "#3D2510", borderRadius: 999,
                  border: "1.5px solid #8A5A00",
                  boxShadow: "0 3px 0 #8A5A00, inset 0 1px 0 rgba(255,255,255,0.4)",
                  fontSize: 10, letterSpacing: "0.18em",
                  whiteSpace: "nowrap",
                  animation: "preSessionGlow 1.6s ease-in-out infinite",
                }}>
                  🎋 Bonus — keep running!
                </div>
              </div>
            )}

            {/* SCROLLING OBSTACLES — sit on the ground, scroll right→left.
                Platforms (kind === "platform") render floating at altitude o.h. */}
            {obstacles.map((o) => (
              <div key={o.id} className="absolute pointer-events-none" style={{
                left: o.x,
                bottom: o.kind === "platform" ? 50 + (o.h - DASH.PLATFORM_THICKNESS) : 50,
                zIndex: 7,
                width: o.w,
                height: o.kind === "platform" ? DASH.PLATFORM_THICKNESS + 4 : o.h,
              }}>
                <DashObstacle type={o.type} w={o.w} h={o.h} />
                {o.kind === "platform" && o.coin && !o.coinTaken && (
                  (o.coinCount || 1) > 1 ? (
                    <div className="absolute flex gap-1.5" style={{ left: o.w / 2 - 17, top: -28 }}>
                      <GoldCoin size={20} />
                      <GoldCoin size={20} />
                    </div>
                  ) : (
                    <div className="absolute" style={{ left: o.w / 2 - 11, top: -28 }}>
                      <GoldCoin size={22} />
                    </div>
                  )
                )}
              </div>
            ))}

            {/* PUFFLING — fixed x position, jumps vertically via direct DOM
                transform updated by the rAF loop. Cute running bobble while
                grounded; rotation wobble when stunned. */}
            <div className="absolute" style={{
              left: DASH.PUFFLING_X, bottom: 56, zIndex: 11,
              width: DASH.PUFFLING_W, height: DASH.PUFFLING_H,
            }}>
              {coinPop && (
                <div className="absolute font-display font-bold dmg-float inline-flex items-center gap-1" style={{ left: 6, top: -22, fontSize: 15, color: "#FFD83A", textShadow: "0 2px 0 rgba(0,0,0,0.4)", whiteSpace: "nowrap", pointerEvents: "none", zIndex: 20 }}>
                  +{coinPopAmt} <GoldCoin size={15} />
                </div>
              )}
              <div
                ref={pufflingDOMRef}
                style={{
                  width: "100%", height: "100%",
                  transition: "filter 200ms",
                  filter: dashStunned ? "saturate(0.7) brightness(0.95)" : "none",
                }}
              >
                <div className={dashStunned ? "" : "dashRun"}>
                  <Puffling state="happy" size={62} belt="orange" />
                </div>
                {/* Stun stars overhead — three small ones for impact */}
                {dashStunned && (
                  <>
                    <div className="absolute" style={{
                      top: -16, left: 0, zIndex: 14, pointerEvents: "none",
                      fontSize: 16, animation: "sparkleSpin 0.7s ease-in-out infinite",
                    }}>💫</div>
                    <div className="absolute" style={{
                      top: -20, left: 18, zIndex: 14, pointerEvents: "none",
                      fontSize: 14, animation: "sparkleSpin 0.6s ease-in-out infinite 0.15s",
                    }}>⭐</div>
                    <div className="absolute" style={{
                      top: -14, left: 32, zIndex: 14, pointerEvents: "none",
                      fontSize: 12, animation: "sparkleSpin 0.8s ease-in-out infinite 0.3s",
                    }}>✨</div>
                  </>
                )}
              </div>
            </div>

            {/* TAP TO START overlay — centered, big, glowing. Shows from
                the moment the session starts until the user's first jump.
                Disappears the instant they tap (which also kicks off scroll,
                spawning, and scoring). */}
            {sessionStarted && !hasJumped && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none" style={{ zIndex: 15 }}>
                <div className="text-center" style={{
                  padding: "18px 30px 20px",
                  background: "linear-gradient(180deg, rgba(255,232,180,0.96) 0%, rgba(251,187,5,0.92) 100%)",
                  borderRadius: 22,
                  border: "2.5px solid #C28A00",
                  boxShadow: "0 6px 0 #8A5A00, 0 0 28px rgba(251,187,5,0.55), inset 0 1px 0 rgba(255,255,255,0.5)",
                  animation: "tapToStartPulse 1.4s ease-in-out infinite",
                }}>
                  <div style={{ fontSize: 30, marginBottom: 2, lineHeight: 1 }}>🎋</div>
                  <div className="font-display font-bold uppercase" style={{
                    fontSize: 20, color: "#3D2510", letterSpacing: "0.1em",
                    textShadow: "0 1px 0 rgba(255,255,255,0.55)",
                    lineHeight: 1.1,
                  }}>Tap to Start</div>
                  <div className="font-body font-bold uppercase" style={{
                    fontSize: 10, color: "rgba(61,37,16,0.7)",
                    letterSpacing: "0.18em", marginTop: 4, lineHeight: 1,
                  }}>tap anywhere to jump</div>
                </div>
              </div>
            )}
          </>
        )}

        {/* AUDIO-ONLY LISTENING VIEW — when the user opted out of the game,
            show a calm centered Puffling instead. High zIndex covers any
            game elements that might otherwise be visible underneath. */}
        {sessionMode === "audio" && sessionStarted && (
          <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none" style={{
            zIndex: 11,
          }}>
            <div style={{
              animation: audioPlaying ? "preSessionGlow 1.6s ease-in-out infinite" : "none",
            }}>
              <BattlePuffling state="idle" facing="right" size={130} belt="orange" />
            </div>
            <div className="font-display font-bold uppercase mt-4" style={{
              fontSize: 11,
              color: "rgba(255,238,196,0.7)",
              letterSpacing: "0.24em",
            }}>
              🎧 Listen and Shadow
            </div>
            <div className="font-body italic mt-1" style={{
              fontSize: 11,
              color: "rgba(255,238,196,0.45)",
            }}>
              Repeat each phrase out loud
            </div>
          </div>
        )}

        {/* TOWER — boards stack from base upward. During finalChopping each
            board renders as two halves with chopAway animations. Gated to kata
            mode so placed boards don't linger after switching to dash. */}
        {sessionMode === "kata" && (
        <div className="absolute inset-x-0 pointer-events-none" style={{
          bottom: towerBase, height: 1, transition: "bottom 220ms ease-out",
        }}>
          {stack.map((b, i) => {
            // i = 0 is the oldest/widest (bottom). i = stack.length-1 is newest (top).
            if (finalChopping) {
              return (
                <div key={i} className="absolute" style={{
                  left: b.x, bottom: i * BOARD_HEIGHT, width: b.width, height: 20,
                }}>
                  {/* Top half — flies up and to the right, rotating clockwise */}
                  <div className="absolute" style={{
                    left: 0, top: 0, width: b.width, height: 10,
                    background: i % 2 === 0
                      ? "linear-gradient(180deg, #C9905A 0%, #B07C46 100%)"
                      : "linear-gradient(180deg, #B07F50 0%, #98683A 100%)",
                    borderTop: "1.5px solid #5A3A1A",
                    borderLeft: "1.5px solid #5A3A1A",
                    borderRight: "1.5px solid #5A3A1A",
                    borderTopLeftRadius: 3, borderTopRightRadius: 3,
                    boxShadow: "inset 0 1px 0 rgba(255,230,180,0.3)",
                    animation: `chopAwayTop 900ms cubic-bezier(0.36, 0, 0.66, 0.5) 700ms forwards`,
                  }} />
                  {/* Bottom half — falls down and to the left, rotating counter-clockwise */}
                  <div className="absolute" style={{
                    left: 0, bottom: 0, width: b.width, height: 10,
                    background: i % 2 === 0
                      ? "linear-gradient(180deg, #B07C46 0%, #A06A38 100%)"
                      : "linear-gradient(180deg, #98683A 0%, #885832 100%)",
                    borderBottom: "1.5px solid #5A3A1A",
                    borderLeft: "1.5px solid #5A3A1A",
                    borderRight: "1.5px solid #5A3A1A",
                    borderBottomLeftRadius: 3, borderBottomRightRadius: 3,
                    boxShadow: "0 1px 0 rgba(0,0,0,0.25)",
                    animation: `chopAwayBottom 900ms cubic-bezier(0.36, 0, 0.66, 0.5) 700ms forwards`,
                  }} />
                </div>
              );
            }
            // Normal whole board during gameplay
            return (
              <div
                key={i}
                className="absolute"
                style={{
                  left: b.x, bottom: i * BOARD_HEIGHT, width: b.width, height: 20,
                  background: i % 2 === 0
                    ? "linear-gradient(180deg, #C9905A 0%, #A06A38 100%)"
                    : "linear-gradient(180deg, #B07F50 0%, #885832 100%)",
                  border: "1.5px solid #5A3A1A", borderRadius: 3,
                  boxShadow: "inset 0 1px 0 rgba(255,230,180,0.3), 0 1px 0 rgba(0,0,0,0.25)",
                  backgroundImage: `${i % 2 === 0
                    ? "linear-gradient(180deg, #C9905A 0%, #A06A38 100%)"
                    : "linear-gradient(180deg, #B07F50 0%, #885832 100%)"
                  }, repeating-linear-gradient(90deg, rgba(80,40,10,0.18) 0px, rgba(80,40,10,0.18) 1px, transparent 1px, transparent 8px)`,
                  backgroundBlendMode: "overlay",
                }}
              />
            );
          })}
          {/* Bonus coins — float at their target rows above the current top.
              Disappear once a board reaches that row (kept ones counted; missed
              ones can be retried after a tower reset until collected). */}
          {sessionStarted && !finalChopping && KATA_COIN_ROWS.flatMap((cfg) =>
            Array.from({ length: cfg.count }).map((_, k) => {
              const key = `c${cfg.row}_${k}`;
              if (collectedKata.has(key) || cfg.row <= stack.length) return null;
              const cx = kataCoinX(cfg.count, k);
              return (
                <div key={key} className="absolute" style={{
                  left: cx - 11, bottom: (cfg.row - 1) * BOARD_HEIGHT - 1, zIndex: 6,
                }}>
                  <GoldCoin size={22} />
                </div>
              );
            })
          )}
        </div>
        )}

        {/* Kata coin grab — brief "+N" pop in the action zone */}
        {sessionMode === "kata" && coinPop && (
          <div className="absolute font-display font-bold dmg-float inline-flex items-center gap-1" style={{ left: "50%", top: "30%", transform: "translateX(-50%)", fontSize: 20, color: "#FFD83A", textShadow: "0 2px 5px rgba(0,0,0,0.55)", zIndex: 40, pointerEvents: "none", whiteSpace: "nowrap" }}>
            +{coinPopAmt} <GoldCoin size={20} />
          </div>
        )}

        {/* Bonus-coin counter — appears the moment you grab your first coin and
            stays pinned top-right for the rest of the session (Bamboo Dash + tower). */}
        {dashCoins > 0 && (
          <div className="absolute inline-flex items-center gap-1.5 font-display font-bold" style={{
            bottom: 16, right: 14, zIndex: 35,
            padding: "5px 12px 5px 8px",
            background: "linear-gradient(180deg, rgba(26,30,60,0.82) 0%, rgba(26,30,60,0.64) 100%)",
            border: "1.5px solid rgba(255,216,58,0.7)", borderRadius: 999,
            boxShadow: "0 2px 8px rgba(0,0,0,0.4)",
            color: "#FFE89A", fontSize: 15, lineHeight: 1,
          }}>
            <GoldCoin size={17} />
            {dashCoins}
          </div>
        )}

        {/* Sliding board — hidden during final chop AND in audio-only mode
            (otherwise the default-width slider div renders at left:0 with
            no animation, showing a phantom plank under the Puffling). */}
        {sessionStarted && !finalChopping && sessionMode === "kata" && (
          <div
            ref={slidingRef}
            className="absolute"
            style={{
              bottom: towerBase + stack.length * BOARD_HEIGHT,
              left: 0, width: slideWidth.current, height: 20, willChange: "transform",
              background: "linear-gradient(180deg, #E0AC72 0%, #B57B40 100%)",
              border: "1.5px solid #5A3A1A", borderRadius: 3,
              boxShadow: "inset 0 1px 0 rgba(255,230,180,0.4), 0 2px 6px rgba(0,0,0,0.4)",
              opacity: 1, transition: "bottom 220ms ease-out",
              backgroundImage: "linear-gradient(180deg, #E0AC72 0%, #B57B40 100%), repeating-linear-gradient(90deg, rgba(80,40,10,0.18) 0px, rgba(80,40,10,0.18) 1px, transparent 1px, transparent 8px)",
              backgroundBlendMode: "overlay",
            }}
          />
        )}

        {/* Hint shown for the first couple boards. "Stack" is accurate —
            users place boards UP onto the tower; the chop only happens at
            session end. Animation is a simple opacity pulse (the previous
            `sparkle` keyframe rotates and made the text spin/unreadable). */}
        {sessionStarted && !finalChopping && sessionMode === "kata" && stack.length < 2 && (
          <div className="absolute pointer-events-none font-display font-bold uppercase" style={{
            top: 8, left: 12, fontSize: 9.5, color: "rgba(255,238,196,0.7)",
            letterSpacing: "0.18em", animation: "hintFade 1.6s ease-in-out infinite",
          }}>tap to stack</div>
        )}

        {/* PERFECT / CHOP / MISS popup */}
        {feedback && !finalChopping && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="font-display font-bold" style={{
              fontSize: feedback.type === "PERFECT" ? 38 : feedback.type === "MISS" ? 42 : 26,
              color: feedback.type === "PERFECT" ? "#FFD83A"
                   : feedback.type === "MISS"    ? "#FF5555"
                                                 : "#FFEEC4",
              letterSpacing: "0.06em",
              textShadow: feedback.type === "MISS"
                ? "0 4px 0 rgba(80,0,0,0.7), 0 0 24px rgba(255,85,85,0.6)"
                : "0 4px 0 rgba(0,0,0,0.5), 0 0 24px rgba(255,216,58,0.5)",
              animation: "comboPop 400ms cubic-bezier(0.34, 1.56, 0.64, 1)",
              WebkitTextStroke: feedback.type === "PERFECT" ? "1.5px #8B4513"
                              : feedback.type === "MISS"    ? "1.5px rgba(80,0,0,0.9)"
                                                            : "1px rgba(0,0,0,0.4)",
            }}>
              {feedback.type === "PERFECT" ? "PERFECT!" : feedback.type === "MISS" ? "MISS!" : "CHOP!"}
            </div>
          </div>
        )}

        {/* Combo */}
        {combo > 1 && !finalChopping && (
          <div className="absolute font-display font-bold" style={{
            top: 38, left: 12, fontSize: 14, color: "#FFD83A",
            textShadow: "0 2px 0 rgba(0,0,0,0.4)", letterSpacing: "0.04em",
          }}>🔥 ×{combo}</div>
        )}

        {/* CHOP FLASH — bright white tint at the moment of Puffling's chop impact */}
        {chopFlash && (
          <div className="absolute inset-0 pointer-events-none" style={{
            background: "rgba(255, 255, 255, 0.6)",
            animation: "chopFlash 250ms ease-out forwards",
            zIndex: 20,
          }} />
        )}

        {/* Big "X BOARDS!" celebration after the chop */}
        {showChopCount && (
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none" style={{ zIndex: 25 }}>
            <div className="font-display font-bold text-center" style={{
              animation: "chopCountPop 600ms cubic-bezier(0.34, 1.56, 0.64, 1) forwards",
            }}>
              <div style={{
                fontSize: 80,
                color: "#FFD83A",
                textShadow: "0 6px 0 rgba(123,60,5,0.85), 0 0 40px rgba(255,216,58,0.7)",
                WebkitTextStroke: "2px #8B4513",
                lineHeight: 1,
                fontVariantNumeric: "tabular-nums",
              }}>
                {totalChopped}
              </div>
              <div style={{
                fontSize: 14,
                color: "#FFEEC4",
                letterSpacing: "0.18em",
                textShadow: "0 2px 0 rgba(0,0,0,0.6)",
                marginTop: 10,
              }}>
                BOARDS CHOPPED!
              </div>
            </div>
          </div>
        )}

        {/* START SESSION overlay */}
        {!sessionStarted && (
          <div className="absolute inset-0 flex flex-col items-center justify-center" style={{
            background: "rgba(0,0,0,0.35)", backdropFilter: "blur(3px)",
            WebkitBackdropFilter: "blur(3px)", zIndex: 20,
          }}>
            {/* Mode picker — three pills, user taps to select which session
                style they want. Selection commits when they press START. */}
            <div className="text-center mb-3" style={{ maxWidth: 248 }}>
              <div className="font-display font-bold" style={{ fontSize: 16, color: "#FFFFFF", textShadow: "0 2px 4px rgba(0,0,0,0.45)" }}>Add a game while you shadow?</div>
              <div className="font-body font-semibold" style={{ fontSize: 12, color: "rgba(255,238,196,0.8)", lineHeight: 1.4, marginTop: 4 }}>
                Optional — just earns <b style={{ color: "#FFD83A" }}>shop coins</b>. Speaking along is the real training.
              </div>
            </div>
            <div className="flex flex-col gap-2 mb-4" style={{ width: 240 }}>
              <ModePickerPill
                mode="kata"
                selected={selectedMode === "kata"}
                icon="🥋"
                title="Kata"
                desc="Bonus game · stack boards"
                onClick={() => setSelectedMode("kata")}
              />
              <ModePickerPill
                mode="dash"
                selected={selectedMode === "dash"}
                icon="🎋"
                title="Bamboo Dash"
                desc="Bonus game · cozy runner"
                onClick={() => setSelectedMode("dash")}
              />
              <ModePickerPill
                mode="audio"
                selected={selectedMode === "audio"}
                icon="🎧"
                title="Audio Only"
                desc="No game · just the training"
                onClick={() => setSelectedMode("audio")}
              />
            </div>

            <button
              onClick={startSession}
              data-sound="cta"
              className="tactile font-display font-bold flex items-center justify-center gap-2"
              style={{
                padding: "16px 32px", borderRadius: 18,
                background: "linear-gradient(180deg, #FFE066 0%, #FFA94D 60%, #E87822 100%)",
                color: "#3D2A05", fontSize: 16, letterSpacing: "0.14em",
                border: "1.5px solid #B85020",
                boxShadow: "0 5px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.45), 0 8px 22px rgba(255,169,77,0.35)",
              }}
            >
              <span style={{ fontSize: 18 }}>▶</span>
              <span>START SESSION</span>
            </button>
            <div className="font-body italic text-center mt-3" style={{
              fontSize: 11, color: "rgba(255,238,196,0.55)",
              maxWidth: 280, lineHeight: 1.4,
            }}>
              Switch modes anytime during the session.
            </div>
          </div>
        )}
      </div>

      {/* Stats row — current tower live + best so far once they've chopped.
          Hidden in non-kata modes (no tower in play) and before the session
          actually starts (no game running yet, so no boards to count). */}
      {sessionMode === "kata" && sessionStarted && (
        <div className="relative flex items-center justify-center gap-3 px-3 mb-2 z-10" style={{
          opacity: finalChopping ? 0 : 1, transition: "opacity 400ms",
        }}>
          <ShadowStatPill icon="🪵" label="Tower" value={stack.length} />
          {totalChopped > 0 && (
            <ShadowStatPill icon="🏆" label="Best" value={bestTower} />
          )}
        </div>
      )}

      {/* Play dots + speed selector — fade out during final chop */}
      <div className="relative px-4 pb-4 z-10" style={{
        opacity: finalChopping ? 0 : 1, transition: "opacity 400ms",
      }}>
        {/* Speed selector — play counter dots removed; progress in the
            phrase banner above already shows where you are in the reps. */}
        <div className="flex items-center justify-center gap-1.5">
          <span className="font-body font-bold uppercase mr-1" style={{
            fontSize: 9, color: "rgba(255,238,196,0.5)", letterSpacing: "0.14em",
          }}>Speed</span>
          {SHADOW_SPEEDS.map((s) => {
            // The first play of each phrase is locked to 0.7× (slow + clear).
            // While that locked playback is happening, ONLY the 0.7× pill is
            // lit — not the chosen speed — so two pills never light at once.
            const firstPlayLock = playIdx === 0 && audioPlaying;
            const lit = firstPlayLock ? s === 0.7 : chosenSpeed === s;
            return (
              <button
                key={s}
                onClick={() => setChosenSpeed(s)}
                className="tactile"
                style={{
                  padding: "5px 11px", borderRadius: 999,
                  background: lit
                    ? "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)"
                    : "rgba(255,238,196,0.08)",
                  color: lit ? "#3D2A05" : "rgba(255,238,196,0.6)",
                  fontSize: 11, fontWeight: 800,
                  border: `1.5px solid ${lit ? "#B85020" : "rgba(255,238,196,0.18)"}`,
                  boxShadow: lit ? "0 2px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.4)" : "none",
                  cursor: "pointer",
                }}
              >{s}×</button>
            );
          })}
        </div>
      </div>

      <style>{`
        @keyframes pufflingChop {
          /* Karate chop with real body movement: windup jump → land + chop
             down + impact squash → small rebound → settle. Squash/stretch
             on the scale (scaleX≠scaleY) makes the impact feel weighty
             instead of being a simple tilt. */
          0%   { transform: translate(0, 0)     rotate(0deg)   scale(1, 1); }
          18%  { transform: translate(2px, -8px) rotate(-10deg) scale(1.04, 0.95); }
          48%  { transform: translate(8px, 5px)  rotate(-18deg) scale(0.93, 1.06); }
          72%  { transform: translate(4px, 1px)  rotate(-8deg)  scale(1, 1); }
          100% { transform: translate(0, 0)     rotate(0deg)   scale(1, 1); }
        }
        @keyframes armChop {
          /* Karate-chop arm swing — windup → swing down past the body →
             fade. Timing aligned with the body's land at ~48%. Pivots
             from the shoulder (left edge). */
          0%   { opacity: 0;   transform: rotate(-40deg); }
          10%  { opacity: 1;   transform: rotate(-55deg); }
          48%  { opacity: 1;   transform: rotate(60deg);  }
          78%  { opacity: 0.5; transform: rotate(40deg);  }
          100% { opacity: 0;   transform: rotate(15deg);  }
        }
        @keyframes preSessionGlow {
          0%, 100% { opacity: 0.7; transform: scale(1); }
          50%      { opacity: 1;   transform: scale(1.06); }
        }
        @keyframes zenItemAppear {
          /* Gentle pop-in for newly placed garden items — small overshoot
             then settle, with opacity fade so it feels like the item
             "arrives" softly rather than snapping in. */
          0%   { opacity: 0; transform: scale(0.5) translateY(4px); }
          70%  { opacity: 1; transform: scale(1.08) translateY(0); }
          100% { opacity: 1; transform: scale(1) translateY(0); }
        }
        .dashRun {
          animation: dashRun 0.32s ease-in-out infinite;
        }
        @keyframes dashRun {
          /* Cute running bobble for the puffling — quick up-down hop with
             slight rotation so it looks like they're jogging in place. */
          0%, 100% { transform: translateY(0)    rotate(0deg); }
          50%      { transform: translateY(-3px) rotate(-2deg); }
        }
        @keyframes redFlashFade {
          /* Brief red overlay across the canvas on collision. Starts opaque,
             fades to nothing over 260ms — clear "you hit something" signal. */
          0%   { opacity: 1; }
          100% { opacity: 0; }
        }
        @keyframes tapToStartPulse {
          /* Gentle scale pulse on the TAP TO START card — gives it that
             "press me" appeal without being distracting. */
          0%, 100% { transform: scale(1); }
          50%      { transform: scale(1.06); }
        }
        @keyframes pauseButtonPulse {
          /* Subtle breathing on the pause button so it reads as
             interactive without screaming for attention. */
          0%, 100% { transform: scale(1); filter: brightness(1); }
          50%      { transform: scale(1.04); filter: brightness(1.08); }
        }
        @keyframes petalFall {
          /* Continuous gentle drift downward with slight horizontal sway
             and rotation. Fades in at top and out near bottom. */
          0%   { transform: translate(0, 0)         rotate(0deg);   opacity: 0; }
          6%   { opacity: 0.95; }
          50%  { transform: translate(14px, 170px)  rotate(180deg); opacity: 0.95; }
          92%  { opacity: 0.95; }
          100% { transform: translate(-6px, 340px)  rotate(360deg); opacity: 0; }
        }
        @keyframes koiSwim {
          /* Subtle side-to-side body sway for the koi fish — gives the
             illusion of swimming in place. */
          0%, 100% { transform: translateX(0) scaleX(1); }
          50%      { transform: translateX(6px) scaleX(0.97); }
        }
        @keyframes pointsRise {
          0%   { transform: translateY(0)   scale(0.7); opacity: 0; }
          15%  { transform: translateY(-4px) scale(1.15); opacity: 1; }
          30%  { transform: translateY(-10px) scale(1); opacity: 1; }
          100% { transform: translateY(-50px) scale(0.9); opacity: 0; }
        }
        @keyframes pufflingFinalChop {
          0%   { transform: translate(0, 0) scale(1) rotate(0deg); }
          25%  { transform: translate(-8px, -18px) scale(1.1) rotate(15deg); }
          45%  { transform: translate(22px, 6px) scale(1.3) rotate(-30deg); }
          55%  { transform: translate(22px, 6px) scale(1.25) rotate(-25deg); }
          75%  { transform: translate(8px, 3px) scale(1.05) rotate(-5deg); }
          100% { transform: translate(0, 0) scale(1) rotate(0deg); }
        }
        @keyframes chopAwayTop {
          0%   { transform: translate(0, 0) rotate(0deg); opacity: 1; }
          100% { transform: translate(90px, -200px) rotate(70deg); opacity: 0; }
        }
        @keyframes chopAwayBottom {
          0%   { transform: translate(0, 0) rotate(0deg); opacity: 1; }
          100% { transform: translate(-60px, 110px) rotate(-35deg); opacity: 0; }
        }
        @keyframes chopFlash {
          0%   { opacity: 1; }
          100% { opacity: 0; }
        }
        @keyframes chopCountPop {
          0%   { transform: scale(0.3); opacity: 0; }
          50%  { transform: scale(1.2); opacity: 1; }
          75%  { transform: scale(0.95); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
        @keyframes hintFade {
          0%, 100% { opacity: 0.4; }
          50%      { opacity: 0.9; }
        }
      `}</style>
    </div>
  );
};

/* Small stat pill used in the Shadow header strip */
const ShadowStatPill = ({ icon, label, value }) => (
  <div className="flex items-center gap-1.5 rounded-full" style={{
    padding: "5px 11px 5px 9px",
    background: "rgba(255,238,196,0.08)",
    border: "1px solid rgba(255,238,196,0.18)",
  }}>
    <span style={{ fontSize: 12 }}>{icon}</span>
    <span className="font-display font-bold" style={{
      fontSize: 13,
      color: "#FFEEC4",
      fontVariantNumeric: "tabular-nums",
    }}>{value}</span>
    <span className="font-body uppercase" style={{
      fontSize: 8.5,
      color: "rgba(255,238,196,0.5)",
      letterSpacing: "0.14em",
      marginLeft: 2,
    }}>{label}</span>
  </div>
);

/* ============================================================
   SHADOW SUMMARY — end-of-session results screen.
   Shows total boards broken, best tower, perfect chops, star
   rating, and the Recall buff awarded.
   ============================================================ */
const ShadowSummary = ({ totalBoards, totalPerfects, bestTower, score, sessionMode, dashDistance = 0, dashBestStreak = 0, dashCoins = 0, phrasesCount, totalReps, onComplete }) => {
  // Coins reward sound — both summary layouts (kata + dash/audio) show the same
  // "Coins earned" card with a coin-drop animation landing ~600ms after mount.
  const shadowCoins = (totalReps || 0) + (dashCoins || 0);
  // Reps climb from zero first, then coins — same sequenced reveal as every
  // other module's completion screen.
  const displayReps  = useCountUp(0, totalReps || 0, 900, 150);
  const displayCoins = useCountUp(0, shadowCoins, 1000, 1300);
  useEffect(() => {
    if ((totalReps || 0) <= 0) return;
    const t = setTimeout(() => playSound("reps-summary"), 150);
    return () => clearTimeout(t);
  }, [totalReps]);
  useEffect(() => {
    if (shadowCoins <= 0) return;
    const t = setTimeout(() => playSound("coins"), 1300);
    return () => clearTimeout(t);
  }, [shadowCoins]);

  // Non-kata modes (dash, audio) skipped the tower-stack scoring system,
  // so there's no tier/buff to grade. Render a calmer "training complete"
  // panel. Dash shows the distance run; audio shows just the rep tally.
  if (sessionMode !== "kata") {
    const isDash = sessionMode === "dash";
    return (
      <div className="relative w-full h-full overflow-y-auto no-scrollbar" style={{
        background: "linear-gradient(180deg, #2D1F12 0%, #3D2A18 50%, #4A3220 100%)",
      }}>
        <div className="relative flex flex-col items-center justify-center px-5 py-8" style={{ minHeight: "100%" }}>
          <div className="font-body font-bold uppercase mb-1" style={{
            fontSize: 11, color: "rgba(255,238,196,0.6)", letterSpacing: "0.24em",
          }}>
            🥊 Warm-Up Complete
          </div>
          <h1 className="font-display font-bold" style={{
            fontSize: 32, color: "#FFEEC4", letterSpacing: "0.02em",
            textShadow: "0 4px 12px rgba(0,0,0,0.5)",
            textAlign: "center",
          }}>
            NICE WORK
          </h1>
          <div className="font-body italic mt-2 mb-6 text-center" style={{
            fontSize: 12, color: "rgba(255,238,196,0.55)",
            maxWidth: 260, lineHeight: 1.4,
          }}>
            {isDash
              ? "Your Puffling ran the path, flowing through every phrase. Its form sharpens with every rep."
              : "Your Puffling moved through every phrase. Its form gets sharper with every rep."}
          </div>
          <div className={isDash ? "grid grid-cols-3 gap-2 w-full max-w-xs mb-4" : "grid grid-cols-2 gap-2 w-full max-w-xs mb-4"}>
            {isDash ? (
              <>
                <SummaryStat icon="🎋" label="Total" value={`${dashDistance}m`} />
                <SummaryStat icon="🔥" label="Best Streak" value={`${dashBestStreak}m`} accent />
                <SummaryStat icon="🔁" label="Reps" value={displayReps} />
              </>
            ) : (
              <>
                <SummaryStat icon="💬" label="Phrases" value={phrasesCount} />
                <SummaryStat icon="🔁" label="Reps" value={displayReps} accent />
              </>
            )}
          </div>

          {/* Coins earned — 1 per rep */}
          <div className="relative flex items-center gap-2.5 mb-7 rounded-2xl px-5 py-3 pop overflow-hidden" style={{ background: "linear-gradient(180deg, #FFF4C8 0%, #FFE89A 100%)", border: "1.5px solid #D4A81F", boxShadow: "0 4px 0 rgba(168,127,15,0.25)" }}>
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="absolute pointer-events-none" style={{ top: -12, left: `${12 + i * 14}%`, animation: `coinDrop 1s ease-in ${1300 + i * 90}ms both` }}>
                <GoldCoin size={13 + (i % 2) * 4} />
              </div>
            ))}
            <GoldCoin size={30} />
            <div className="relative" style={{ zIndex: 2 }}>
              <div className="font-body font-bold uppercase" style={{ fontSize: 9, color: "#7A5410", letterSpacing: "0.16em" }}>Coins earned</div>
              <div className="font-display font-bold" style={{ fontSize: 22, color: "#3D2A05", lineHeight: 1.1 }}>+{displayCoins}</div>
              {dashCoins > 0 && (
                <div className="font-body font-bold inline-flex items-center gap-1" style={{ fontSize: 9.5, color: "#7A5410" }}>incl. +{dashCoins} from Bamboo Dash <GoldCoin size={11} /></div>
              )}
            </div>
          </div>
          <button
            onClick={() => onComplete({ sessionMode, phrasesCount, totalReps, dashDistance, dashBestStreak, dashCoins })}
            className="tactile font-display font-bold flex items-center justify-center gap-2"
            style={{
              padding: "13px 28px", borderRadius: 16,
              background: "linear-gradient(180deg, #FFE066 0%, #FFA94D 60%, #E87822 100%)",
              color: "#3D2A05", fontSize: 14, letterSpacing: "0.14em",
              border: "1.5px solid #B85020",
              boxShadow: "0 4px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.45)",
            }}
          >
            <span>⚔️</span>
            <span>BEGIN RECALL</span>
          </button>
        </div>
      </div>
    );
  }

  // Star rating thresholds — score-based (the headline metric).
  // With the continuous-tower model, score ranges:
  //   timid play (lots of topples, narrow chops): ~1-3k
  //   solid play (a few good runs, some perfects): ~4-8k
  //   strong play (long towers + many perfects + combos): 10k+
  const stars = score >= 8000 ? 3 : score >= 4500 ? 2 : score >= 1500 ? 1 : 0;
  // Performance grade for the warm-up (score-based headline only — NOT a combat
  // buff; Shadowing does not buff Recall battles).
  const tier =
    stars === 3 ? { label: "MASTERED",   color: "#FFD83A" } :
    stars === 2 ? { label: "FORM FOUND", color: "#FFA94D" } :
    stars === 1 ? { label: "TRAINED",    color: "#C8A8F0" } :
                  { label: "PRACTICED",  color: "#FFEEC4" };

  return (
    <div className="relative w-full h-full overflow-y-auto no-scrollbar" style={{
      background: "linear-gradient(180deg, #2D1F12 0%, #3D2A18 50%, #4A3220 100%)",
    }}>
      <div className="relative flex flex-col items-center justify-center px-5 py-8" style={{ minHeight: "100%" }}>
        {/* Title */}
        <div className="font-body font-bold uppercase mb-1" style={{
          fontSize: 11,
          color: "rgba(255,238,196,0.6)",
          letterSpacing: "0.24em",
        }}>
          🥊 Warm-Up Complete
        </div>
        <h1 className="font-display font-bold" style={{
          fontSize: 36,
          color: tier.color,
          letterSpacing: "0.03em",
          textShadow: "0 4px 12px rgba(0,0,0,0.5)",
          WebkitTextStroke: "1.5px rgba(0,0,0,0.3)",
          textAlign: "center",
        }}>
          {tier.label}
        </h1>

        {/* Puffling — emotional arc lands here: just trained, now combat-
            ready, leaning into the Recall fight that follows. Fighting
            stance with pump-up sparkles (gold this time — bridges Shadow's
            cool palette into Recall's warm one). Only visible for non-zero
            tiers (otherwise the user "practiced" — no pump-up earned). */}
        {stars > 0 && (
          <div className="relative mt-2 mb-1" style={{ animation: "battleIdle 2.4s ease-in-out infinite" }}>
            <BattlePuffling state="fighting" facing="right" size={110} belt="orange" />
            <div className="absolute" style={{ top: -2, right: -6, fontSize: 18, animation: "sparkleSpin 2s ease-in-out infinite" }}>✨</div>
            <div className="absolute" style={{ bottom: 8, left: -10, fontSize: 14, animation: "sparkleSpin 2.4s ease-in-out infinite 0.6s" }}>✨</div>
          </div>
        )}

        {/* Stars */}
        <div className="flex items-center gap-2 mt-3 mb-5">
          {[0, 1, 2].map((i) => (
            <div key={i} style={{
              fontSize: 32,
              filter: i < stars ? "drop-shadow(0 0 12px rgba(255,216,58,0.7))" : "grayscale(100%) opacity(0.25)",
              animation: i < stars ? `numberRise 400ms ${i * 150}ms backwards` : "none",
            }}>
              ⭐
            </div>
          ))}
        </div>

        {/* Stat grid */}
        <div className="grid grid-cols-3 gap-2 w-full max-w-xs mb-5">
          <SummaryStat icon="🪵" label="Boards" value={totalBoards} />
          <SummaryStat icon="⭐" label="Score" value={score.toLocaleString()} accent />
          <SummaryStat icon="🏆" label="Best tower" value={bestTower} />
        </div>

        {/* Coins earned — 1 per rep */}
        <div className="relative flex items-center gap-2.5 w-full max-w-xs mb-6 rounded-2xl px-5 py-3 pop overflow-hidden" style={{ background: "linear-gradient(180deg, #FFF4C8 0%, #FFE89A 100%)", border: "1.5px solid #D4A81F", boxShadow: "0 4px 0 rgba(168,127,15,0.25)" }}>
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="absolute pointer-events-none" style={{ top: -12, left: `${12 + i * 14}%`, animation: `coinDrop 1s ease-in ${1300 + i * 90}ms both` }}>
              <GoldCoin size={13 + (i % 2) * 4} />
            </div>
          ))}
          <GoldCoin size={30} />
          <div className="relative" style={{ zIndex: 2 }}>
            <div className="font-body font-bold uppercase" style={{ fontSize: 9, color: "#7A5410", letterSpacing: "0.16em" }}>Coins earned</div>
            <div className="font-display font-bold" style={{ fontSize: 22, color: "#3D2A05", lineHeight: 1.1 }}>+{displayCoins}</div>
            {dashCoins > 0 && (
              <div className="font-body font-bold inline-flex items-center gap-1" style={{ fontSize: 9.5, color: "#7A5410" }}>incl. +{dashCoins} from the tower <GoldCoin size={11} /></div>
            )}
          </div>
        </div>

        {/* Done CTA — leads straight into Recall */}
        <button
          onClick={() => onComplete({ score, totalBoards, totalPerfects, stars, totalReps, phrasesCount, dashCoins })}
          className="tactile font-display font-bold flex items-center justify-center gap-2"
          style={{
            padding: "13px 28px",
            borderRadius: 16,
            background: "linear-gradient(180deg, #FFE066 0%, #FFA94D 60%, #E87822 100%)",
            color: "#3D2A05",
            fontSize: 14,
            letterSpacing: "0.14em",
            border: "1.5px solid #B85020",
            boxShadow: "0 4px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.45)",
          }}
        >
          <span>⚔️</span>
          <span>BEGIN RECALL</span>
        </button>
      </div>
    </div>
  );
};

const SummaryStat = ({ icon, label, value, accent = false }) => (
  <div className="rounded-2xl text-center" style={{
    padding: "10px 6px 9px",
    background: accent
      ? "linear-gradient(180deg, #FFE066 0%, #FFA94D 100%)"
      : "rgba(255,238,196,0.08)",
    border: accent ? "1.5px solid #B85020" : "1.5px solid rgba(255,238,196,0.18)",
    boxShadow: accent ? "0 2px 0 #B85020, inset 0 1px 0 rgba(255,255,255,0.45)" : "none",
  }}>
    <div style={{ fontSize: 15, lineHeight: 1 }}>{icon}</div>
    <div className="font-display font-bold" style={{
      fontSize: 19,
      color: accent ? "#3D2A05" : "#FFEEC4",
      lineHeight: 1.05,
      marginTop: 2,
      fontVariantNumeric: "tabular-nums",
    }}>
      {value}
    </div>
    <div className="font-body font-bold uppercase" style={{
      fontSize: 8,
      color: accent ? "#7A2D0A" : "rgba(255,238,196,0.55)",
      letterSpacing: "0.12em",
      marginTop: 1,
    }}>
      {label}
    </div>
  </div>
);
